    'cli.doctor.provider_none' => 'nenhum selecionado — o backend de eco offline responderá (defina CANDY_CODE_PROVIDER)',
    'cli.doctor.provider_shell' => 'backend shell-out (nível $CANDY_CODE_BACKEND_CMD)',
    'cli.doctor.provider_unconstructable' => '{provider} está selecionado, mas não pode ser construído: {error}',
    'cli.doctor.provider_unknown' => '{provider} está selecionado, mas não é um provedor conhecido — veja `candy-code models`',
    'cli.doctor.sandbox_binary' => '{backend} em {path}',
    'cli.doctor.sandbox_binary_absent' => '{backend} não encontrado no PATH',
    'cli.doctor.sandbox_nonlinux' => 'bashSandbox "{mode}" está configurado, mas bubblewrap é exclusivo do Linux e este host é {os}',
    'cli.doctor.sandbox_nonlinux_off' => 'bashSandbox está desativado; bubblewrap é exclusivo do Linux e este host é {os}',
    'cli.doctor.sandbox_off' => 'bashSandbox está desativado; {bwrap}, e a jail iniciaria aqui se estivesse habilitada',
    'cli.doctor.sandbox_off_blocked' => 'bashSandbox está desativado; {bwrap}, e a jail não iniciaria aqui mesmo se estivesse habilitada ({reason})',
    'cli.doctor.sandbox_ready' => 'bashSandbox "{mode}"; {bwrap}, e a jail inicia',
    'cli.doctor.sandbox_refused' => 'bashSandbox "{mode}" está configurado, mas a jail não inicia ({reason}) — {remedy}',
    'cli.doctor.sandbox_remedy_apparmor' => 'instale bubblewrap, ou adicione um perfil em /etc/apparmor.d concedendo a bwrap namespaces de usuário sem privilégios (o sysctl apparmor_restrict_unprivileged_userns é o fallback grosseiro)',
    'cli.doctor.sandbox_remedy_generic' => 'instale bubblewrap, ou defina bashSandbox como "off"',
    'cli.doctor.sandbox_remedy_seatbelt' => 'verifique se /usr/bin/sandbox-exec ainda executa nesta instalação do macOS, ou defina bashSandbox como "off"',
    'cli.doctor.server_ready' => 'pcntl, posix e ffi disponíveis — `serve` pode iniciar',
    'cli.doctor.server_refuses' => '`serve` recusará iniciar: {problems}',
    'cli.doctor.sessions' => '{count} sessão(ões) armazenada(s)',
    'cli.doctor.settings_clean' => 'cada arquivo de configurações contém apenas chaves que candy-code lê',
    'cli.doctor.unknown' => 'desconhecido',
    'cli.headless.permission_hint' => '  dica: uma execução `-p` sem modo nomeado inicia no modo `default` que pergunta; perguntas sem supervisão não têm ninguém para responder, então falham fechadas. Execuções scriptadas podem nomear --permission-mode bypass-permissions (ou accept-edits) para continuar.',
    'cli.help.screen' => <<<'TXT'
CandyCode — assistente de programação com IA para o terminal.

Uso:
  candy-code                       Inicia a TUI interativa (padrão)
  candy-code <dir>                 Inicia a TUI com raiz em <dir>, que deve
                                   existir (somente como primeiro argumento)
  candy-code [<dir>] <palavras…>   Inicia a TUI e envia as palavras como seu
                                   primeiro prompt, ex.: candy-code fix the bug
  candy-code -c                    Continua a sessão mais recente
  candy-code --resume [<id>]       Retoma uma sessão armazenada (seletor se sem id)
  candy-code -p <prompt>           Executa um único prompt e sai (one-shot)
  candy-code run "<prompt>"        Alias para -p "<prompt>" (modo one-shot)
  candy-code --output-format json  Saída JSON legível por máquina (one-shot)
  candy-code --worktree [<name>]   Executa esta sessão em um git worktree
                                   próprio (criado se não existir)

Subcomandos (nenhum deles abre a TUI nem precisa de provedor, chave de API ou
terminal; cada um responde e sai, exceto serve e mcp serve, que rodam até
parados — e attach, que é a exceção a ambos: executa a TUI na sessão de um servidor em execução
; acp executa turnos para um editor, até o editor desconectar):
  bundles list           Lista os bundles de plugins que este diretório vê: nome,
                         versão, nível e as superfícies que cada um traz —
                         incluindo os hooks e .mcp.json que candy-code
                         se recusa a executar.
  bundles install <src>  Copia um diretório de bundle, ou clona uma URL git com
                         clone de profundidade um limitado, para a raiz de bundles
                         do usuário (~/.candy-code/bundles), onde só você é dono.
  doctor                 Verifica esta instalação e reporta todo problema que
                         encontra: versão do PHP, extensões que o armazenamento de
                         sessões e serve precisam, arquivo de configuração, política
                         de permissões, provedor selecionado, banco de dados de
                         sessões e configuração MCP do projeto. Sai com 1 se alguma
                         verificação FALHAR.
                         Distinto da ferramenta "doctor" chamável pelo modelo, que
                         reporta o protocolo de imagens do terminal ao modelo.
  import claude          Pré-visualiza a importação das configurações do Claude Code: lê o arquivo
                         de configurações do usuário do Claude, além do arquivo de configurações .claude
                         sob a raiz de execução quando --project é informado, traduz suas listas
                         de permissões allow/deny/ask para permissionRules (o lado mais
                         restritivo sempre vence — deny prevalece sobre allow), mapeia o modelo e nomeia
                         cada chave sem destino como skipped. Nada é gravado até
                         confirmação: --yes aceita a pré-visualização impressa diretamente, e
                         sem ele um terminal interativo é consultado. A pré-visualização nomeia
                         cada regra allow que ampliaria o que roda sem perguntar.
  login <provider>       Autentica um provedor: claude-code e codex entregam o
                         terminal ao próprio CLI deles (o token nunca passa
                         pelo candy-code); openai, anthropic e gemini
                         colam uma chave no bloco providers do arquivo de configuração;
                         os demais nomeiam quem realmente detém sua credencial.
  models                 Lista os provedores que esta instalação pode selecionar e o
                         modelo padrão de cada um; "*" marca o
                         selecionado.
  session list [--all|--archived|--children] [--limit N]
                         Lista sessões armazenadas, fixadas primeiro e depois as mais
                         recentes: id, última atualização, tipo, turnos, provedor/modelo
                         e nome (★ marca uma linha fixada). --children adiciona
                         linhas de subagente e segundo plano, --archived adiciona
                         as arquivadas, --all adiciona ambas; 20 linhas a menos que
                         --limit diga o contrário.
  session show <target>  Imprime os detalhes e a transcrição de uma sessão.
  session import <path> [--format auto|…] [--name <title>] [--force]
                         Importa um arquivo de transcrição como nova sessão:
                         uma exportação candy-code ou o histórico de
                         claude-code, codex ou opencode (--format nomeia, auto deduz).
  session rename <target> <title…>
                         Renomeia uma sessão; as palavras após o target são
                         o título.
  session delete <target> [--with-children]
                         Exclui uma sessão. Filhos subagente vão junto;
                         ramificações são mantidas a menos que --with-children.
  session pin|unpin|archive|unarchive <target>
                         Fixa uma sessão (listada primeiro, nunca expurgada), ou
                         arquiva (oculta da lista padrão, mantida).
                         <target> é um id, um nome ou um prefixo de id único.
                         Sai com 1 se nada corresponder, 2 se um prefixo for
                         ambíguo (os candidatos são listados).
  mcp list               Lista os servidores MCP declarados em .mcp.json, SEM
                         iniciar nenhum deles. Informa em vez disso quando o arquivo
                         está ausente, resolve fora da árvore do projeto, ou está
                         presente mas a raiz do projeto não é confiável.
  mcp auth login <server> [token-url] [authorize-url] [registration-url]
                         Autentica um servidor MCP declarado com OAuth: abre
                         (ou imprime) o URL de autorização, capta o redire-
                         cionamento de loopback e guarda os tokens para depois.
  mcp trust              Aprova o .mcp.json deste projeto como está: adiciona
                         a raiz a "trustedProjectMcp" e registra o comando, os args e o env de cada
                         servidor, para que uma alteração posterior em
                         qualquer um deles seja recusada na execução até nova aprovação.
                         Não inicia nada.
  mcp import claude|opencode|claude-project <path> [--write user]
                         Traduz uma configuração MCP estrangeira e imprime o
                         bloco .mcp.json equivalente no stdout. Imprime apenas
                         por padrão; --write user anexa as entradas traduzidas
                         ao ~/.candy-code/mcp.json do próprio usuário
                         (uma colisão de nome recusa a gravação inteira, e o
                         nível de projeto nunca é gravado). As renomeações que a
                         tradução fez são listadas no stderr.
  mcp serve [--root PATH]
                         Serve o candy-code em si como servidor MCP via stdio:
                         um quadro JSON-RPC por linha na entrada, uma resposta por linha
                         na saída, até o stdin fechar. Chamadas de ferramentas executam o
                         conjunto somente-leitura (Read, Glob, Grep, Ls, RepoMap), confinado à
                         raiz do workspace, através do PermissionGate da execução
                         e da cadeia de hooks PreToolUse — este é o servidor
                         MCP que um cliente pode iniciar; o WebSocket
                         `candy-code serve` ainda não fala MCP. Roda até
                         ser parado.
  lsp install <language> Instala o servidor de linguagem fixado para um
                         idioma: o pacote npm ou o binário de versão verificado por checksum,
                         na raiz de instalação privada sob o seu diretório
                         pessoal. `lsp list` informa quais idiomas são
                         instaláveis.
  lsp list               Informa cada idioma instalável: sua versão
                         fixada, onde seu servidor está instalado (ou que
                         não está), e se existe uma versão para o SO e
                         arquitetura desta máquina. Não inicia nada,
                         não baixa nada.
  self-update [--check] [--rollback] [--allow-unsigned] [--channel=stable|dev]
                         Substitui esta instalação phar pela versão publicada mais
                         recente do candy-code, verificada por sha256 contra o
                         sidecar da versão ANTES da troca; o phar em execução é
                         mantido como <phar>.old e --rollback restaura exatamente
                         essa cópia uma vez. Quando uma chave pública de assinatura é fixada
                         na fonte da versão, a assinatura candy-code.phar.minisig
                         também deve verificar (--allow-unsigned pula
                         apenas essa etapa). --check apenas informa atual vs
                         mais recente e sai com 1 quando há atualização disponível. Uma
                         instalação via Composer é recusada com veemência, nomeando o
                         comando composer update a executar em vez disso. Uma instalação
                         de desenvolvimento segue a versão contínua candy-code/dev
                         por padrão (está atual quando o commit alvo da versão
                         corresponde ao sha do carimbo) e --channel
                         seleciona explicitamente uma das trilhas.
  serve [--host <ip>] [--port <n>] [--allow-remote] [--allowed-host <list>]
        [--allowed-ips <list>] [--allowed-origin <list>] [--allow-dir-browse]
        [--browse-root <dir>] [--web-root <dir>] [--no-web] [--allow-bypass]
        [--allow-root] [--detach] [--parent-pid <pid>]
        [--tls-cert <file>] [--tls-key <file>]
                         Executa o servidor WebSocket + HTTP usado pela interface web,
                         em primeiro plano até Ctrl+C. Vincula a 127.0.0.1:7420
                         por padrão e exibe uma URL de acesso cujo código
                         de uso único é trocado por um cookie do navegador; todo
                         cliente precisa dele ou do token em ~/.candy-code/server/token,
                         incluindo loopback. Opções:
      --host <ip>        Endereço a vincular (padrão 127.0.0.1; localhost e ::1
                         também contam como loopback). Qualquer outro endereço é recusado
                         a menos que --allow-remote também seja informado.
      --port <n>         Porta a vincular (padrão 7420; 0 escolhe uma livre).
      --allow-remote     Permite um --host não-loopback. Sem --tls-cert e
                         --tls-key isso é HTTP puro: coloque um proxy reverso TLS
                         na frente, ou sirva TLS diretamente (veja abaixo). Em
                         0.0.0.0 ou :: o servidor responde aos próprios endereços
                         desta máquina, e a URL de acesso os lista.
      --tls-cert <file>  Certificado PEM com o qual o próprio listener serve TLS,
                         informado junto com --tls-key. A URL de acesso então
                         usa https://, o cookie de sessão carrega Secure,
                         e um cliente http:// em texto puro não recebe resposta.
      --tls-key <file>   Chave privada PEM para --tls-cert: arquivo legível sem
                         bits de grupo ou mundo expostos, compatível com o certificado.
                         Um par inválido ou incompleto é recusado na inicialização.
      --allowed-host <list>
                         Nomes de host extras (ou host:porta) separados por vírgula
                         aos quais o servidor responde, ex.: um nome DNS desta máquina.
                         Repetível.
      --allowed-ips <list>
                         IPs de cliente ou faixas CIDR separados por vírgula (ex.:
                         1.2.3.4,10.0.0.0/8) autorizados a conectar; qualquer outro
                         endereço recebe 403 antes do acesso. Loopback é
                         sempre permitido. Não definido: sem filtro de endereço.
                         Repetível.
      --allowed-origin <list>
                         Origens de navegador extras separadas por vírgula
                         (http(s)://host[:porta]) permitidas além da do próprio
                         servidor. Repetível.
      --allow-dir-browse Permite que clientes autenticados escolham o diretório de
                         início de uma nova sessão: podem listar nomes de diretórios
                         (nunca arquivos) sob --browse-root. Desativado por padrão.
      --browse-root <dir>
                         Diretório ao qual --allow-dir-browse fica restrito
                         (padrão: seu diretório home).
      --web-root <dir>   Serve a interface web de <dir> em vez do pacote
                         sugarcraft/candy-code-web instalado.
      --no-web           Serve apenas a API e o WebSocket, sem arquivos de UI.
      --allow-bypass     Permite sessões em bypass-permissions ou dont-ask
                         (recusado por padrão; as sessões do servidor iniciam em
                         default a menos que --permission-mode diga o contrário).
      --allow-root       Permite executar como root (recusado por padrão).
      --detach           Executa em segundo plano: exibe a URL e o pid uma vez
                         que a porta é vinculada, e sai; o servidor registra em
                         server.log no seu diretório de estado.
      --parent-pid <pid> Para o servidor quando o processo <pid> encerra (para um
                         editor ou TUI que inicia um servidor privado).
                         Recusa iniciar sem ext-pcntl, ext-posix e
                         ext-ffi (veja doctor). Sai com 1 se a porta estiver ocupada ou
                         um servidor já rodar do mesmo diretório de estado.
  serve status           Informa o servidor em execução: pid, URL, root, tempo ativo e
                         se GET /api/health responde. Sai com 1 quando nenhum
                         está rodando.
  serve stop [--force]   Para o servidor: SIGTERM, até 30 s para drenar, depois SIGKILL.
      --force            SIGKILL imediato.
  serve logs [-f]        Exibe o final do log de um servidor em segundo plano.
  -f, --follow           Continua exibindo o que é acrescentado até parar.
  serve url [--qr]       Exibe uma URL de acesso com um código de uso único novo.
      --qr              Renderiza cada URL de acesso como um QR code escaneável no terminal.
  serve token [--rotate] Exibe o token de proprietário que clientes bearer enviam.
      --rotate           Substitui-o; um servidor em execução mantém o antigo até
                         reiniciar.
  attach [<session>] [--url <url>]
                         Executa a TUI em uma sessão de um candy-code
                         serve em execução: o servidor roda cada turno e suas ferramentas, e
                         este terminal as exibe e responde às perguntas
                         de permissão que elas levantam. <session> é um id, um nome ou um
                         prefixo de id único de uma das sessões do servidor;
                         sem ele, uma nova é criada. O servidor é
                         o que serve status informa, seu token obtido de
                         CANDY_CODE_SERVER_TOKEN ou do arquivo de token
                         do diretório de estado. Sair desanexa; um turno em execução
                         continua. Sai com 1 se nenhum servidor responder.
      --url <url>        Anexa ao servidor em <url> (o endereço que serve
                         exibe) em vez disso.
  acp                    Executa como agente do Agent Client Protocol: o editor
                         (Zed, JetBrains, Neovim) o inicia e fala
                         JSON-RPC em seu stdin e stdout. Sessões abrem em
                         raiz do projeto do editor, os turnos executam aqui com este
                         provedor e ferramentas da instalação, e o editor responde
                         às perguntas de permissão. Não para terminal: stdout
                         transporta apenas o protocolo (todo o resto vai para
                         stderr). Sai com 0 quando o editor fecha stdin.
  completion bash|zsh|fish
                         Escreve um script de completamento de shell no stdout, ex.:
                         eval "$(candy-code completion bash)".
  usage [7|30|all] [--session <target>]
                         Resume o livro-razão de gastos persistente por dia e modelo:
                         a mesma página que `/usage` imprime, sobre o mesmo
                         agregado compartilhado. 7 e 30 usam dias UTC inteiros
                         incluindo hoje, all (ou sem operando) abrange todo o
                         livro-razão, e uma janela fora desse conjunto é
                         recusada em vez de ser alargada silenciosamente.
                         --session restringe a uma sessão por id, nome ou
                         prefixo único; --output-format json emite o mapa de
                         fatos a partir do qual a página foi construída. Um
                         livro-razão ilegível informa o motivo e sai com 1;
                         dólares para agregados que incluem um modelo sem
                         preço são impressos como limite inferior ≥, nunca
Opções:
  -p, --prompt <text>    Fornece um prompt na linha de comando (modo one-shot)
      --output-format <format>
                         Formato de saída: "text" (padrão), "json" ou
                         "stream-json" (eventos NDJSON, resposta por último)
      --root <dir>       Usa <dir> como raiz do projeto em vez do diretório
                         atual. Também aceita --root=<dir> (a forma a usar
                         quando <dir> começa com "-"); não pode ser omitido.
                         Nomear uma raiz aqui E como argumento posicional é
                         recusado em vez de uma vencer silenciosamente.
      --config <file>    Lê configurações, permissões e raízes de hooks
                         confiáveis de <file> em vez de ~/.candy-code/config.json.
                         Também aceita --config=<file>. Deve já existir, ser
                         legível, pertencer a você, e nem ele nem seu
                         diretório podem ser graváveis por todos — ele carrega
                         a política de permissão, então é mantido ao mesmo
                         padrão de ~/.candy-code/config.json (um arquivo sob
                         /etc ou /tmp é normalmente recusado por um desses
                         motivos). Apenas o ARQUIVO muda: agentes, skills,
                         workflows, sessões e memória permanecem em ~/.candy-code.
      --model <name>     Usa <name> como modelo da conversa, substituindo
                         $CANDY_CODE_MODEL e o padrão do próprio provedor. Também
                         aceita --model=<name>. Seleciona um modelo, não um
                         provedor — o provedor ainda vem de $CANDY_CODE_PROVIDER
                         ou da configuração `provider` persistida, e os dois
                         são eixos independentes.
      --permission-mode <mode>
                         Executa sob <mode> em vez do modo no arquivo de
                         config. Também aceita --permission-mode=<mode>. Maior
                         precedência: sobrepõe $CANDY_CODE_PERMISSION_MODE e
                         a chave de config permissionMode. Um de: default,
                         accept-edits, plan, auto, dont-ask,
                         bypass-permissions. Sem nenhum definido, a TUI e -p
                         iniciam em default (pergunta antes de escritas e
                         comandos de shell); apenas um daemon iniciado
                         localmente começa em bypass-permissions.
      --max-cost <usd>   Limita esta execução a <usd> dólares US de gastos
                         reportados: o turno que cruzaria o teto é recusado
                         e não enviado. Também aceita --max-cost=<usd>.
                         Maior precedência: sobrepõe $CANDY_CODE_MAX_COST e
                         a chave de config maxCostUsd. Fracionário permitido,
                         um $ inicial aceito ($2.50); zero e negativos são
                         recusados em vez de lidos como "sem limite". /budget
                         ainda aumenta ou limpa o limite para a sessão em
                         execução.
      --max-turns <n>    Limita esta execução a <n> passos do loop de
                         ferramentas: o turno que os usa todos para onde
                         está e informa. Também aceita --max-turns=<n>.
                         Maior precedência: sobrepõe a chave de config
                         maxToolSteps (este eixo não tem variável de
                         ambiente). Um número inteiro positivo; zero é
                         recusado em vez de lido como "sem limite", e um
                         valor inutilizável recusa a execução em vez de
                         ceder silenciosamente à configuração.
      --json-schema <path-or-json>
                         Restringe a resposta a um JSON Schema: um documento
                         {"type":"object",...} inline ou um caminho para um
                         arquivo contendo um. Também aceita
                         --json-schema=<value>; a forma = é a a usar quando
                         o caminho começa com "-". Apenas provedores que
                         reportam suporte a respostas restritas por schema
                         executam a requisição — qualquer outro recusa com
                         exit 2 em vez de faturar por uma resposta sem
                         restrição. O schema controla a requisição de
                         auto-encerramento do turno; passos que continuam
                         um loop de ferramentas ficam livres (uma resposta
                         JSON forçada não pode carregar chamadas de
                         ferramentas).
      --append-system-prompt <text-or-@file>
                         com "-". As regras chegam como mais um bloco
                         de instrução pessoal, nunca uma substituição: elas
                         não podem substituir nem rebaixar as camadas acima, e
                         marcadores de bloco forjados no texto são neutralizados.
                         Limitado ao mesmo tamanho de um documento de instrução.
                         Somente com -p ou o verbo run: uma execução sem
                         prompt para anexar recusa com exit 2 em vez de
                         ignorar silenciosamente as regras que você forneceu.
  -c, --continue         Reabre a sessão usada mais recentemente, transcript
                         e tudo, em vez de iniciar uma nova. Sem ele,
                         toda execução abre uma nova sessão; Up em uma
                         caixa de entrada vazia ainda recupera prompts de sessões anteriores.
      --resume [<id|name>]
                         Reabre uma sessão armazenada por id, prefixo único de id ou
                         nome (veja `session list`). Sem valor, abre o
                         seletor de sessões na execução; junto com -p um destino É
                         obrigatório (o transcript alimenta a execução única e a
                         resposta é salva de volta na linha). Também aceita
                         --resume=<id>. Não combinável com --continue.
      --worktree [<name>]
                         Executa toda a sessão dentro de um git worktree
                         main-<name> na branch candy-code/<name>, criado
                         no primeiro uso; sem nome, o worktree recebe um
                         nome autoescolhido. Na saída, um worktree sem
                         commits e sem edições é removido; um com
                         trabalho permanece e anuncia seu caminho. Recusado
                         fora de um git work tree e junto com `serve`.
      --incognito        Execução que não guarda nada: sem linha de sessão, sem
                         transcript, sem gravações automáticas de memória ao fim do turno.
                         O que a execução produziu vive apenas no processo;
                         sessões e notas armazenadas ANTERIORMENTE permanecem legíveis.
                         Recusado junto com --continue ou --resume, que reabrem
                         sessões guardadas.
      --restricted       Execução que não pode rodar código: Bash, PtyRun, Task,
                         Workflow, ShellStop e mcp_call são removidos de
                         todo conjunto voltado ao modelo durante toda a sessão, e
                         /permissions não pode devolvê-los. Ferramentas de arquivo permanecem,
                         sob o confinamento de caminho existente. Também aceita
                         --restricted=true|false, para que um wrapper possa sobrepor
                         um alias com a flag simples. Sobrevive a relançamento.
      --safe-mode        Execução que ignora toda confiança: cada raiz
                         de projeto confiável responde como não confiável (hooks,
                         MCP e shells de comando), nenhum bundle carrega, e nenhum
                         skill, comando ou agente externo é descoberto.
                         Configurações, skills e comandos nativos permanecem. Também
                         aceita --safe-mode=true|false para sobrepor um
                         alias. Sobrevive a relançamento.
  -h, --help             Mostra esta mensagem de ajuda
  -v, --version          Mostra a versão instalada e sai
      --                 Fim das opções: todo argumento posterior é posicional,
                         nunca uma flag

Variáveis de ambiente:
   CANDY_CODE_PROVIDER    Provedor a usar: openai, azure, anthropic, claude-code,
                          codex, sglang, bedrock, vertex, gemini,
                          openrouter, custom
   CANDY_CODE_MODEL       Nome do modelo (substitui o padrão do provedor; --model vence)
   CANDY_CODE_PERMISSION_MODE
                          Modo de permissão inicial, substituindo a
                          chave de configuração permissionMode (--permission-mode vence)
   CANDY_CODE_BACKEND_CMD Comando de shell para um adaptador de backend custom, sob o
                          contrato PROSE: recebe histórico JSON no stdin, escreve
                          o texto da resposta no stdout, que é usado verbatim
                          (podado apenas nas duas extremidades, então cada newline, linha
                          em branco e indentação internos sobrevivem).
   CANDY_CODE_BACKEND_CMD_STREAM
                          O mesmo shell-out sob o outro contrato, um TOKEN
                          STREAM: um token por linha, o newline entre dois
                          tokens é enquadramento e é descartado, e uma linha EM BRANCO é
                          um newline literal na resposta. O callback dispara por
                          token conforme o comando os produz, mas o loop de leitura
                          é síncrono, então a tela é redesenhada uma vez no final
                          em vez de token por token. Não intercambiável com
                          CANDY_CODE_BACKEND_CMD em qualquer direção — um wrapper
                          prose executado por esta variável volta com todos os
                          newlines removidos e cada linha em branco colapsada em uma.
                          CANDY_CODE_BACKEND_CMD tem precedência quando ambos estão definidos.
                          Para ambos, não definido, vazio e só com espaços contam
                          como ausentes.
   CANDY_CODE_DISABLE_PARALLEL_TOOL_CALLS
                          Executa as chamadas de ferramentas de um turno estritamente uma por vez.
                          O despacho concorrente é o padrão e só
                          agrupa ferramentas não mutantes; esta é a válvula de escape.
                          Persista como "parallelToolCalls": false em
                          ~/.candy-code/config.json.
   CANDY_CODE_PARALLEL_TOOL_DEADLINE
                          Segundos que um grupo concorrente pode rodar antes que seus
                          retardatários sejam mortos e reportados como chamadas falhas
                          (padrão 90, deve ser 1-119; uma fração é truncada).
                          Persista como "parallelToolDeadlineSeconds".
                          Precedência: esta variável, depois a chave persistida,
                          então o padrão. Um valor fora de 1-119, ou um que
                          não seja um número de forma alguma, não conta como definido — ele
                          cai para a próxima fonte em vez de
                          descartá-la.
   CANDY_CODE_ADVISOR_MODEL
                          O modelo que a ferramenta `Advisor` consulta para uma segunda
                          opinião: uma conclusão sem ferramentas, cobrada como qualquer
                          outra chamada. Diferente de CANDY_CODE_TITLE_MODEL, não
                          há fallback barato — não definido significa que a ferramenta
                          não é oferecida de forma alguma. Lido no início.
   CANDY_CODE_TITLE_MODEL O modelo barato usado para nomear automaticamente uma sessão após
                          sua primeira troca; padrão é o do provedor.
   CANDY_CODE_SUMMARY_MODEL
                          O modelo que escreve resumos de compactação;
                          padrão é o da própria conversa, que reutiliza
                          o cache de prompt.
   CANDY_CODE_CONTEXT_PRUNING
                          auto, manual ou off: como uma sessão faz a poda do
                          contexto quando /pruning não escolheu (padrão auto).
   CANDY_CODE_MAX_COST    Um teto de gastos para esta execução, em dólares
                          (fracionário permitido; um "$" inicial é aceito;
                          --max-cost vence). Um turno que ultrapassa o teto
                          é recusado.
   CANDY_CODE_CONNECT_TIMEOUT
                          Limite da fase de conexão, em segundos (fracionário
                          permitido; padrão 15.0), para transportes HTTP
                          de provedores. Limita apenas o estabelecimento da conexão
                          — não é um timeout total da requisição. Quanto tempo
                          um servidor streaming conectado pode levar para enviar seus
                          cabeçalhos de resposta é a configuração separada
                          streamHeaderTimeoutSeconds.
   CANDY_CODE_SEARCH_ENDPOINT
                          API de busca que a ferramenta WebSearch integrada consulta.
   CANDY_CODE_SESSION_RETENTION_DAYS
                          Um número inteiro positivo de dias: cada execução descarta
                          sessões intocadas por pelo menos esse tempo.
   CANDY_CODE_SHARE_UPLOAD_URL
                          Host de upload aposentado: /share nunca faz upload
                          para lugar nenhum. Quando definido, a exportação local ainda é
                          gerada e a resposta recusa a chave em voz alta e menciona
                          /share serve, que publica uma página de snapshot
                          auto-hospedada no seu próprio candy-code serve.
   CANDY_CODE_WORKTREES_DIR
                          Diretório base sob o qual worktrees de git
                          por colega de equipe são criados.
   CANDY_CODE_DISABLE_MOUSE
                          Qualquer valor diferente de vazio ou 0 desliga o
                          rastreamento do mouse por completo.
   CANDY_CODE_DISABLE_MOUSE_CLICKS
                          Qualquer valor diferente de vazio ou 0 ignora gestos de clique
                          mantendo a rolagem com a roda.
   CANDY_CODE_DISABLE_PROMPT_CACHE
                          Qualquer valor diferente de vazio ou 0 desliga os
                          breakpoints de cache de prompt do provedor.
   CANDY_CODE_DISABLE_PROMPT_SUGGESTIONS
                          Qualquer valor diferente de vazio ou 0 para a sugestão
                          de próxima mensagem em cinza (→ aceita) após cada turno.
   CANDY_CODE_DISABLE_AUTO_MEMORY
                          Qualquer valor diferente de vazio ou 0 para o salvamento
                          automático de fatos duráveis como notas após um turno, e
                          a passagem de sonho que dobra o diário de compactação
                          nelas.
   CANDY_CODE_DISABLE_MODEL_METADATA
                          Qualquer valor diferente de vazio ou 0 para a leitura e
                          atualização do banco de dados de modelos LiteLLM que dimensiona e
                          precifica modelos sem valor embutido.
   CANDY_CODE_NO_UPDATE_CHECK
                          Qualquer valor diferente de vazio ou 0 para a verificação diária de
                          release phar e o aviso de atualização na inicialização que ela alimenta;
                          nenhuma requisição sai do processo e um aviso em cache
                          obsoleto não é mais exibido.
   CANDY_CODE_DISABLE_SYMBOL_MAP
                          Qualquer valor diferente de vazio ou 0 mantém o mapa
                          de símbolos ranqueado fora do prompt de sistema.
   CANDY_CODE_BACKGROUND  light ou dark — força o que o tema adaptativo
                          acredita sobre o fundo do terminal, pulando
                          a sonda OSC 11 e COLORFGBG.
   CANDY_CODE_DEBUG_SKILLS
                          Qualquer valor diferente de vazio ou 0 coloca as linhas
                          de SkillLoader por-skip e por-diretório-recusado de volta no
                          stderr.
   CANDY_CODE_DEBUG_COMMANDS
                          Qualquer valor diferente de vazio ou 0 coloca as linhas de
                          recusa de descoberta de CommandLoader de volta no stderr.
   CANDY_CODE_DEBUG_RULES Qualquer valor diferente de vazio ou 0 coloca as linhas de
                          recusa de descoberta de RuleLoader de volta no stderr.
   CANDY_CODE_DEBUG_STREAM
                          Qualquer valor diferente de vazio ou 0 mantém a linha
                          "onToken observer threw" de Chat no stderr. O
                          detach em si acontece de qualquer forma.
   CANDY_CODE_SERVER_HOST O endereço que `serve` vincula (--host prevalece).
   CANDY_CODE_SERVER_PORT A porta que `serve` vincula (--port prevalece).
   CANDY_CODE_SERVER_ALLOWED_ORIGINS
                          Origens extras separadas por vírgula que `serve` aceita
                          (--allowed-origin prevalece).
   CANDY_CODE_SERVER_ALLOWED_HOSTS
                          Nomes de host extras separados por vírgula que `serve` responde
                          (--allowed-host prevalece).
   CANDY_CODE_SERVER_ALLOWED_IPS
                          IPs de cliente ou CIDRs separados por vírgula que `serve` admite
                          além do loopback (--allowed-ips prevalece).
   CANDY_CODE_SERVER_WEB_ROOT
                          Diretório de onde `serve` serve a interface web (--web-root
                          prevalece).
   CANDY_CODE_SERVER_TOKEN
                          O token que `serve` exige, em vez do que está em
                          seu diretório de estado (pelo menos 32 caracteres; para
                          contêineres).
   CANDY_CODE_SERVER_DIR  O diretório onde `serve` mantém seu token, lock,
                          registro de descoberta e log (padrão
                          ~/.candy-code/server; criado com 0700).
   CANDY_CODE_SERVER_PARENT_PID
                          Um processo que `serve` encerra com (--parent-pid prevalece).
   CANDY_CODE_MCP_DISABLE
                          1, true ou yes (sem diferenciar maiúsculas) silencia o MCP
                          do projeto por completo: .mcp.json é tratado como inexistente, nenhum
                          servidor inicia. Não definido, 0 ou qualquer outro valor mantém
                          o MCP habilitado — diferente das variáveis de estilo flag,
                          apenas essas três palavras contam.
   CANDY_CODE_QUIET_LOGS  1, true ou yes (sem diferenciar maiúsculas) silencia o
                          canal lateral error_log() em todo o processo em seu único
                          destino; não definido, 0 ou qualquer outro valor mantém os
                          diagnósticos fluindo. Somente no lançamento, sem chave de configuração.
   CANDY_CODE_REDUCED_MOTION
                          1, true ou yes (sem diferenciar maiúsculas) fixa o
                          spinner do agente em um quadro estático — para usuários
                          sensíveis a movimento e com movimento reduzido. Lido uma vez no
                          lançamento; não há chave de configuração.
   CANDY_CODE_SD_BASE_URL URL base do servidor Stable Diffusion estilo
                          A1111 (sdapi) que o transporte de mídia acessa.
                          Precedência: uma substituição explícita no código, depois esta
                          variável, depois a configuração sd.baseUrl.
   CANDY_CODE_MEDIA_RENDER_MODE
                          Como as imagens geradas são renderizadas no terminal
                          (a camada de env da configuração ui.imageRenderMode; veja
                          docs/ENVIRONMENT.md para as palavras aceitas).
   CANDY_CODE_ALLOW_ROOT_TESTS
                          Defina como exatamente 1 para permitir que o TEST SUITE do
                          candy-code execute como root; não definido ou qualquer outro valor, a suíte
                          se recusa a iniciar com euid 0. Nada sobre o
                          lançamento do candy-code muda — a suíte não é uma
                          interface voltada ao usuário.
   CANDY_CODE_TOOL_INPUT  O mapa completo de argumentos da chamada de ferramenta de
                          script do usuário atual, codificado em JSON, exportado para o
                          processo filho de cada execução de uma ferramenta ~/.candy-code/tools;
                          o app escreve, nunca lê de volta, e
                          ninguém o define manualmente.
   CANDY_CODE_OTEL_BATCH_SIZE
                          Quantos spans um lote de exportação OTLP carrega
                          (padrão 64, limitado a 1..2048).
   CANDY_CODE_OTEL_TIMEOUT
                          Segundos que cada tentativa de exportação OTLP pode levar
                          (padrão 3; um valor não positivo ou malformado
                          recorre ao padrão).

   docs/ENVIRONMENT.md tabula todas as variáveis que esta build lê, com seu
   contrato completo.

Códigos de saída (modo one-shot e todos os subcomandos):
  0                      O prompt foi executado e produziu uma resposta, ou o
                         subcomando respondeu
  1                      Executou e falhou: o backend lançou (host inacessível,
                         chave rejeitada, erro de modelo) — uma nova tentativa pode ajudar — ou um
                         subcomando foi executado e falhou (uma verificação do doctor retornou
                         FAIL, um verbo `session` não encontrou a sessão, um
                         .mcp.json confiável não pôde ser analisado)
  2                      Erro de uso ou configuração, nada foi tentado
                         e uma nova tentativa não ajudará: nenhum prompt fornecido, uma
                         flag não reconhecida, um argumento solto que não nomeia
                         um diretório existente (um prompt precisa de -p), um --root
                         que não nomeia um diretório, um composer
                         autoload.php ausente, ou um provedor selecionado
                         que não pode ser construído — seja
                         $CANDY_CODE_PROVIDER ou o provedor persistido em
                         ~/.candy-code/config.json por Ctrl+P "Trocar modelo".
                         Uma execução one-shot nunca recorre ao provedor echo offline
                         quando um provedor foi selecionado explicitamente.
                         Um subcomando com um operando ausente ou desconhecido
                         (`session`, `mcp bogus`, `completion tcsh`) reporta
                         aqui também.
  130/143/129             TUI: um sinal interrompeu o loop — 128+N para
                         SIGINT (Ctrl+C), SIGTERM, SIGHUP; uma saída
                         cooperativa (/exit, q) ainda sai com 0.

Exemplos:
  candy-code -p "Explain the difference between require and include"
  CANDY_CODE_PROVIDER=anthropic CANDY_CODE_MODEL=claude-sonnet-4-20250514 \
    candy-code -p "Write a hello world in Go"
  candy-code run "Write a hello world in Go"
  candy-code doctor
  candy-code models --output-format json | jq '.result.providers'
  eval "$(candy-code completion bash)"
  candy-code serve --port 7420

Para mais informações, consulte o README:
  https://github.com/detain/sugarcraft/tree/master/candy-code

