    'cli.refuse.dangling_directory' => '{dir} é um symlink que não resolve para um diretório que este processo pode pesquisar',
    'cli.refuse.foreign_owner' => '{path} pertence ao uid {uid}, não à conta sob a qual esta sessão está sendo executada, portanto a política de permissões e a cadeia de hooks que ele carrega pertencem a outra pessoa. Recusando iniciar em vez de executar a política de outra conta.',
    'cli.refuse.hook_chain' => '{error} Recusando iniciar em vez de executar com uma cadeia de hooks que não é a configurada.',
    'cli.refuse.hooks_unreachable' => '{path} não pode ser acessado: {reason}, portanto não é possível saber se hooks estão configurados ali. Recusando iniciar em vez de executar com uma cadeia de hooks desconhecida.',
    'cli.refuse.keybindings' => 'a configuração keybindings é inutilizável: {reason}. Remova a chave para executar com os bindings padrão (a referência /keys os nomeia). Recusando iniciar em vez de executar com substituições de teclas que você não definiu.',
    'cli.refuse.max_cost_env' => '$CANDY_CODE_MAX_COST é \'{value}\', que não é um teto de gastos. Esperado um número positivo de dólares (decimais permitidos, $ inicial aceito), por exemplo 5 ou $2.50. Zero e negativos são recusados em vez de lidos como "sem limite" porque são o pedido oposto; um valor grande demais para ser representado (1e309, ou seja, infinito) é recusado porque instalaria um teto que nunca seria atingido. Desconfigure a variável para não ter teto. Recusando iniciar em vez de executar sem teto com um limite que você pediu.',
    'cli.refuse.max_cost_flag' => '--max-cost é \'{value}\', que não é um teto de gastos. Esperado um número positivo de dólares (decimais permitidos, $ inicial aceito), por exemplo 5 ou $2.50. Zero e negativos são recusados em vez de lidos como "sem limite" porque são o pedido oposto; um valor grande demais para ser representado (1e309, ou seja, infinito) é recusado porque instalaria um teto que nunca seria atingido. Remova a flag para não ter teto. Recusando iniciar em vez de executar sem teto com um limite que você pediu.',
    'cli.refuse.max_cost_setting' => 'maxCostUsd nas suas configurações é {value}, que não é um teto de gastos. Esperado um número positivo de dólares, por exemplo 5 ou 2.5. Remova a chave para não ter teto. Recusando iniciar em vez de executar sem teto com um limite que você pediu.',
    'cli.refuse.max_turns_flag' => '--max-turns é \'{value}\', que não é um teto de etapas. Esperado um número inteiro positivo de etapas do loop de ferramentas, por exemplo 8. Zero é recusado em vez de lido como "sem limite" porque é o pedido oposto; um valor grande demais para ser representado é recusado porque instalaria um teto que nunca seria atingido. Remova a flag para usar a configuração maxToolSteps. Recusando iniciar em vez de executar sem teto com um limite que você pediu.',
    'cli.refuse.no_home' => 'este processo não consegue determinar qual diretório home é seu ($HOME não está definido, $USERPROFILE não está definido e não há entrada passwd para seu uid), portanto a política de permissões e a cadeia de hooks em ~/.candy-code não podem ser localizadas. Recusando iniciar em vez de ler qualquer uma delas de um diretório de fallback com escrita para todos — exporte HOME para a conta à qual esta sessão pertence.',
    'cli.refuse.no_project_root' => 'não é possível determinar a raiz do projeto — o diretório de trabalho do processo está indisponível (excluído ou ilegível). Passe --root <dir>.',
