    'cli.selfupdate.staged_windows' => 'candy-code: a atualização está em staging para a troca no relançamento — {new} substitui {path} quando este processo encerra; o progresso é registrado em {path}.swap.log e a cópia mantida permanece em {old}.',
    'cli.selfupdate.swap_leftover' => 'candy-code: um self-update anterior deixou uma troca em staging em {new} que nunca foi aplicada (seu swap log registra as tentativas abandonadas). Esta execução substitui o staging antes de atualizar.',
    'cli.selfupdate.swap_spawn_failed' => 'candy-code: o auxiliar de troca não pôde ser iniciado; os bytes verificados permanecem em staging em {new} e a cópia em execução está intacta. Conclua a renomeação para {path} manualmente, ou execute self-update novamente quando nada estiver segurando o arquivo.',
    'cli.selfupdate.uncomparable' => 'candy-code: esta instalação reporta {current}, que não é uma versão de release que self-update pode ordenar.',
