    'cmd.mcp-auth.login-armed' => "↻ Login MCP iniciado para `{server}` — aguardando o link do navegador.\n\nO processo filho vincula uma porta de loopback; conclua-o em um navegador enquanto a TUI permanece responsiva. O cliente MCP desta sessão memoizou seu armazenamento na inicialização, então o token entra em vigor na PRÓXIMA inicialização; `/mcp list` mostra a credencial assim que for armazenada.",
    'cmd.mcp-auth.login-busy' => '! Um login para `{server}` já está em execução — conclua ou cancele aquele primeiro (sua URL e status estão no transcript acima).',
    'cmd.mcp-auth.login-code-delivered' => '✓ O callback foi entregue ao login aguardando por `{server}` — o processo filho conclui a troca ali, e seu resultado aparece no transcript.',
    'cmd.mcp-auth.login-code-refused' => '! Não foi possível entregar o callback de login MCP para `{server}`: {reason}',
    'cmd.mcp-auth.login-code-reason-dial' => "o listener do login aguardando não respondeu",
