    'cmd.mcp-auth.login-done' => '✓ Login MCP para `{server}` concluído (saída {code}). Tokens são anexados na PRÓXIMA inicialização — inicie uma nova sessão para que o grant acompanhe as requisições; `/mcp list` atualiza o painel.',
    'cmd.mcp-auth.login-failed' => <<<'TXT'
✗ Login MCP para `{server}` saiu com {code} sem armazenar tokens.

As últimas linhas do processo filho estão acima; o mesmo fluxo em um shell (`candy-code mcp auth login {server}`) imprime o erro completo e é o lugar para depurar problemas de endpoint ou porta.
TXT,
    'cmd.mcp-auth.login-failed-spawn' => "✗ Não foi possível iniciar o processo filho de login MCP para `{server}`.\n\nExecute a forma de shell diretamente: `candy-code mcp auth login {server}`.",
    'cmd.mcp-auth.login-guidance' => "O login interativo é um comando de shell, não um turno de chat:\n\n  candy-code mcp auth login <server> [token-url] [authorize-url] [registration-url]\n\nExecuta o fluxo de código de autorização OAuth com PKCE: seu navegador\ndevolve o código a um listener de loopback no shell, e os tokens\narmazenados são anexados aos servidores http correspondentes na próxima inicialização.",
    'cmd.mcp-auth.login-no-entry' => "✗ Não foi possível encontrar o ponto de entrada do próprio programa para fazer fork de `mcp auth login {server}`.\n\nExecute a forma de shell diretamente: `candy-code mcp auth login {server}`.",
    'cmd.mcp-auth.login-served-armed' => "↻ Login MCP iniciado para `{server}` no host do SERVIDOR — o link aparece abaixo; abra-o em um navegador na sua máquina. Seu navegador não consegue alcançar o listener de loopback do servidor diretamente: quando cair em uma página de erro de conexão, copie o endereço dessa página e envie `/mcp login {server} --code <that-url>` para entregar o callback ao login em espera. Os tokens são anexados na PRÓXIMA inicialização; `/mcp list` mostra a credencial assim que for armazenada.",
    'cmd.mcp-auth.login-url' => '→ Abra esta URL para autorizar `{server}`:\n\n  {url}',
    'cmd.mcp-auth.not-found' => '! Nenhuma credencial encontrada para `{server}`.',
    'cmd.mcp-auth.registered' => <<<'TXT'
✓ `{server}` registrado com sucesso
Client ID: `{client}`
Requisições a um servidor MCP http com esta URL exata agora carregam este token automaticamente, renovado antes de expirar; servidores iniciados antes deste comando o adquirem na próxima inicialização.
TXT,
