    'cmd.mcp-auth.reconnect.drifted' => "Configuração MCP alterada desde a inicialização — reconexão recusada. Uma reconexão reinicia os servidores exatamente como `.mcp.json` os contém agora, enquanto esta sessão foi admitida com os bytes que a inicialização confiou; iniciar entradas divergentes executaria servidores que as decisões de admissão nunca viram. Reinicie a sessão para aplicar a alteração; esse é o único caminho de aplicação.",
