    'cmd.mcp-auth.undiscovered' => "! Endpoints OAuth não puderam ser descobertos para `{server}`.\n\nForneça-os explicitamente:\n  `mcp auth add {server}` *<registration-url>* *<token-url>*\n\nNada a descobrir geralmente significa nada a registrar: um\nservidor que não precisa de login roda apenas com seu \"url\" uma vez\ndeclarado em .mcp.json (docs/MCP.md, \"{section}\").",
    'cmd.mcp-auth.unknown' => 'Subcomando desconhecido \'{sub}\'. Use: list, add, remove, login, reconnect, enable, disable',
    'cmd.mcp-auth.usage' => "Uso:\n  mcp auth list                    — lista servidores registrados\n  mcp auth add <server> [reg-url] [token-url]  — armazena credenciais OAuth para um servidor\n  mcp auth remove <server>         — remove as credenciais de um servidor\n  mcp auth login <server>          — imprime o comando de shell para login interativo\n  /mcp reconnect                   — reinicia os servidores declarados, apenas enquanto .mcp.json ainda corresponde à inicialização\n  /mcp enable <server> [--persist]   — remove a recusa desta sessão a um servidor declarado\n  /mcp disable <server> [--persist]  — recusa as chamadas de um servidor declarado nesta sessão",
