    'sandbox.hook.not_run' => 'Não executado: o hook `{hook}` foi isolado no sandbox `{mode}` por sandboxScope, mas o sandbox {name} não pode iniciar neste host ({reason}). Nada foi executado, isolado ou não. Informe o usuário: ele pode corrigir {name} ({remedy}) ou definir bashSandbox como "off".',
