    'sandbox.mcp.not_started' => 'Não iniciado: o servidor MCP `{server}` foi isolado no sandbox `{mode}` por sandboxScope, mas o sandbox {name} não pode iniciar neste host ({reason}). Nada foi iniciado, isolado ou não. Informe o usuário: ele pode corrigir {name} ({remedy}), definir bashSandbox como "off", ou isentá-lo com `"sandbox": false` na sua entrada de nível de usuário.',
