    'sandbox.runner.skipped' => 'Pulado: a execução {scope} foi isolada no sandbox `{mode}` por sandboxScope, mas o sandbox {name} não pode iniciar neste host ({reason}). Nada foi executado, isolado ou não. Informe o usuário: ele pode corrigir {name} ({remedy}) ou definir bashSandbox como "off".',
