    'chat.command.error' => '**Error:** {error}',
    'chat.compact.idle_advisory' => 'Esta sessão está ociosa há mais de uma hora e cresceu para ~{tokens} tokens estimados, ultrapassando sua janela de contexto de {limit} tokens. Execute /compact para reduzir o contexto antes de continuar. Enviar outra mensagem não a enviará como está: o próximo turno está acima do nível de compactação automática, então trocas mais antigas são resumidas primeiro, e o turno é recusado sumariamente se isso não liberar espaço suficiente.',
    'chat.compact.idle_auto_scheduled' => 'Compactação automática por inatividade: a sessão ficou além da janela de inatividade com a transcrição acima do nível de compactação (~{tokens} tokens estimados contra uma janela de {limit} tokens), então a solicitação de resumo foi enviada sem supervisão. O encolhimento entra no próximo turno; nada é cobrado duas vezes e nenhuma resposta é enviada a ninguém.',
    'chat.compact.idle_folded' => 'Compactado durante a inatividade: ~{before} tokens estimados viraram ~{after}. `compaction.idleAuto` executou o nível automático enquanto a sessão ficou intocada, então as trocas que ele condensou agora são resumos.',
