    'chat.goal.none_set' => 'Nenhuma meta definida. `{command} <condition>` define uma: o agente começa nela imediatamente, e após cada turno o modelo de título verifica a transcrição em busca de evidências de que foi atingida, enviando o agente de volta ao trabalho até que seja (até {rounds} rodadas de acompanhamento).',
