    'chat.turn.output_limit' => 'O provedor interrompeu esta resposta no limite de saída, então o texto acima pode terminar no meio de um pensamento. Aumente `maxOutputTokens` em ~/.candy-code/config.json para uma resposta única mais longa, ou peça o restante na sua próxima mensagem.',
    'chat.turn.steps_exhausted' => 'Este turno usou todos os seus passos de ferramenta antes do trabalho terminar, então a resposta acima descreve onde parou — o que está concluído e o que resta — não uma resposta final. Diga `continue` para retomar de onde parou, ou aumente o teto para turnos agênticos mais longos — a flag --max-turns na execução tem precedência sobre a configuração `maxToolSteps` em ~/.candy-code/config.json, então aumente a que estiver em vigor.',
    'chat.turn.unpriced_model' => 'Este app não tem preço cadastrado para o modelo `{model}`, então este turno foi cobrado em $0.00 como limite inferior, não como chamada gratuita — totais de gastos e o teto de gastos ficam subestimados até que uma taxa exista. Declare uma em `modelPrices` em ~/.candy-code/config.json (USD por 1M tokens, chaves `input` e `output`) para precificá-lo.',
