    'host.command_shell.mcp_refused' => '[!`{command}` não foi executado: /{name} é um prompt MCP obtido de um servidor, texto que chegou pela rede. Um corpo obtido tem formas de shell recusadas independentemente do que este projeto confia — liste a chave do servidor sob "mcpPromptShell" na sua própria configuração de usuário para que suas formas de shell alcancem o portão de permissões — o restante do prompt foi enviado.]',
    'host.loop.not_configured' => 'Agendamentos não configurados nesta sessão — /loop não tem relógio para rodar. Uma execução simples de `candy-code` sempre carrega um; uma build de integração com host precisa fornecê-lo.',
