    'host.output_style.footer' => "/output-style <name> seleciona um estilo; exatamente um vigora por vez, e uma\ntroca limpa o anterior. /output-style off limpa o slot. `off` é uma\npalavra reservada — um arquivo chamado off.md não pode ser selecionado. Um estilo desativado pelo seu\npróprio frontmatter (`enabled: false`) fica fora do prompt independentemente de como for nomeado.",
