    'host.schedules.usage' => 'Uso: /schedules [list] | add <name> <interval> <prompt> [--mode <mode>] [--provider <name>] [--heartbeat] | enable <name> | disable <name> | delete <name>. As linhas ficam em ~/.candy-code/schedules.json; /schedules add cria uma pelos limites da fábrica da ferramenta Schedule, /loop registra uma efêmera.',
    'host.schedules.none' => 'Nenhum agendamento. /schedules add <name> <interval> <prompt> cria um pelos mesmos limites da ferramenta Schedule, ou escreva uma linha em ~/.candy-code/schedules.json (`name`, `every` em segundos, `prompt`, `root` — o diretório do projeto onde dispara; opcionais `provider`, `permissionMode` (grafias de bypass são recusadas; omita para o piso não interativo), `enabled`, `timeoutSeconds`, `kind` (`task` responde, `heartbeat` pode ficar em silêncio)), ou /loop um para esta sessão. docs/SCHEDULES.md é o formato.',
