    'host.compact.safeguard.hold' => 'Compactação recusada: o resumo do modelo foi descartado pela auditoria de salvaguarda ({detail}). Nada foi condensado e seu histórico completo foi preservado — execute /compact novamente para pedir ao modelo mais uma vez.',
    'host.compact.self_client_only' => '`/compact --self` pede ao agente que escreva seu próprio resumo — esse é o caminho interativo do TUI. Execute `/compact` para consolidar os resumos escritos pelo modelo já disponíveis para esta sessão.',
