    'host.compact.thrash' => 'A compactação de contexto foi executada {times} vezes seguidas e o transcript voltou acima do limite em todas, então este prompt não foi enviado e nenhuma compactação adicional foi tentada. As trocas recentes que a reescrita mantém por completo são o que não caberá — reduza as maiores (a saída de ferramentas geralmente é o grosso), ou recomece com /rewind ou /clear. /model com uma janela de contexto maior também resolve isso.',
    'host.compact.tier_report' => 'O contexto atingiu o nível de compactação automática, então trocas mais antigas foram resumidas: {before} mensagens -> {after} mensagens, ~{saved}% da contagem estimada de tokens liberados (~{tokens} tokens estimados agora, em uma janela de contexto de {limit} tokens).',
    'host.compact.truncated.one' => '{count} mensagem atingiu {tier} sozinha, então foi truncada para caber na janela de contexto em vez de o turno ser recusado: ~{tokens} tokens estimados agora, em uma janela de contexto de {limit} tokens. O texto enviado ao modelo carrega um marcador onde foi cortado; seu original completo permanece no transcript, oculto do modelo.',
    'host.compact.truncated.other' => '{count} mensagens atingiram {tier} sozinhas, então foram truncadas para caber na janela de contexto em vez de o turno ser recusado: ~{tokens} tokens estimados agora, em uma janela de contexto de {limit} tokens. O texto enviado ao modelo carrega um marcador onde cada uma foi cortada; seus originais completos permanecem no transcript, ocultos do modelo.',
