    // --- fix-tui-interact 2026-10-14 ---
    'tui.picker.notice.slash_filter' => '`{word}` parece um comando de barra, não um filtro — Enter aqui retomaria a melhor correspondência. Pressione Escape e digite o comando na entrada.',
    'tui.app.stop_all_armed' => 'Prestes a parar todos os agentes em execução — pressione "s" novamente em 3 s para confirmar.',

    // --- fix-app-launch 2026-10-14 ---
    'appLaunch.doctor.mbstring_missing' => 'ausente — cálculos de largura de frame (mb_*) não podem ser executados; reinstale o PHP com ext-mbstring',
    'appLaunch.doctor.intl_missing' => 'ausente — cálculos de largura grapheme/IntlChar não podem ser executados; reinstale o PHP com ext-intl',
    'appLaunch.notice.policy_changed' => '⚠ config.json ou hooks.yaml mudaram desde a última execução. Novos hooks do projeto ficam em quarentena apenas nesta execução — revise ~/.candy-code/config.json e hooks.yaml, e então serão respeitados',
    'appLaunch.notice.project_policy_changed' => '⚠ O hooks.yaml de um projeto confiável contém entradas que a última execução nunca viu. Novos hooks do projeto ficam em quarentena apenas nesta execução — revise o .candy-code/hooks.yaml desse repositório, e então serão respeitados',
    'appLaunch.notice.bypass_mode' => '⚠ O modo de permissão é bypass-permissions: toda chamada de ferramenta é executada sem confirmação. Altere com /permissions (TUI), --permission-mode, ou defina um modo de permissão diferente em ~/.candy-code/config.json',
    // C-SEC-7.a: `-p` now defaults to the ASKING mode, so an unattended scripted
    // run that named no mode starts refusing — the launch says so once, and names
    // the one-flag fix. No trailing period — STDERR_LINE_FORMAT adds one
    // (LaunchNoticeOwnPeriodTest).
    'appLaunch.notice.headless_default' => 'ℹ -p inicia no modo de permissão default: uma execução desacompanhada recusa toda chamada de ferramenta que pediria confirmação. Passe --permission-mode (bypass-permissions executa tudo) para execuções scriptadas',
    // C-SEC-7.e (owner ruling t212, option 3): the implicit autoReview default
    // announces once per session the first time it engages — de-duped by message
    // identity in the launch-notices store, like the bypass banner. Names the
    // opt-out and owns up to the money. No trailing period — STDERR_LINE_FORMAT
    // adds one (LaunchNoticeOwnPeriodTest).
    'appLaunch.notice.auto_review_default' => '⚠ autoReview está ativado por padrão nesta execução: chamadas de modo automático sinalizadas são revisadas pelo modelo de título, e cada revisão é uma chamada de modelo paga. Defina autoReview como false em ~/.candy-code/config.json para desativar',
    // C-SEC-6.b: names the file, what it added, and what could not be honoured.
    // No trailing period — STDERR_LINE_FORMAT adds one (LaunchNoticeOwnPeriodTest).
    'appLaunch.notice.project_narrowing_rules' => '⚠ {file} restringiu as permissões desta execução: {count} regra(s) de negar/perguntar carregada(s) primeiro, {dropped} regra(s) de permitir descartada(s) — um arquivo de projeto não pode conceder permitir',
    'appLaunch.notice.restricted' => '⚠ --restricted: esta execução roda sem ferramentas de execução de código — Bash, PtyRun, Task, Workflow, ShellStop e mcp_call estão ausentes de todos os conjuntos voltados ao modelo; ferramentas de arquivo permanecem sob seu confinamento de caminho e /permissions não pode restaurar as ferramentas removidas',
    'appLaunch.notice.safe_mode' => '⚠ --safe-mode: raízes de projetos confiáveis, bundles, e skills, comandos e agentes externos são todos ignorados nesta execução — comporta-se como se nada tivesse sido confiável',

    // --- fix-w2-chat 2026-10-14 ---
    'chat.launch.echo_backend' => 'Nenhum provedor está configurado, então esta sessão roda no backend de eco offline embutido — respostas são ecoadas localmente, nenhum modelo é chamado. Execute `candy-code doctor` para ver o que um provedor precisa, depois pressione Ctrl+P para trocar de modelo quando um estiver configurado.',
    'keys.chat.repaint' => 'Limpar a tela e redesenhar o frame',
    'keys.unbound' => 'não vinculado',

    // --- C-EXT-1 (Claude Code hook dialect) 2026-10-27 ---
    'hooks.notice.advisory' => '⚠ O hook `async` do Claude Code `{hook}` saiu com {code}. Um hook `async` pede para observar uma chamada de ferramenta em vez de bloqueá-la, então não tem poder para bloquear e a chamada prosseguiu. O que ele disse: {reason}',
    'hooks.notice.claude_dialect' => '⚠ O hook do Claude Code `{hook}` saiu com {code}, que o Claude Code lê como uma reclamação não bloqueante em vez de uma decisão, então a chamada de ferramenta prosseguiu. O que ele disse: {reason}',
    'hooks.notice.said_nothing' => '(nada no stderr)',
    'hooks.notice.system_message' => '⚠ O hook `{hook}` deixou uma mensagem para você: {message}',

    // --- C-EXT-6.c (type: http hooks) 2026-10-30 ---
    // Every row names the hook and scheme://host only: never a path, a query,
    // or any header value, so an Authorization cannot ride out of the process
    // inside its own refusal.
    'hooks.http.deny_bad_url' => 'O hook HTTP `{hook}` está configurado com uma URL que não pode ser usada ({reason}); o alvo mostrado é {target}. Um hook que não pode indicar para onde vai não aprovou esta chamada.',
    'hooks.http.deny_scheme' => 'O hook HTTP `{hook}` aponta para {target}, que não é uma URL http ou https. candy-code conecta hooks apenas por esses dois esquemas, e a chamada é recusada em vez de ser executada contra um transporte não verificado.',
    'hooks.http.deny_credentials' => 'O hook HTTP `{hook}` contém credenciais em sua URL ({target}). Uma senha escrita em uma URL acaba em logs e proxies, então é recusada aqui; envie-a como um cabeçalho cujo valor leia um nome de `allowedEnvVars`.',
    'hooks.http.deny_blocked_target' => 'O hook HTTP `{hook}` não pode ser consultado: {reason} ({target}). Endereços privados e link-local são recusados pela mesma regra de uma requisição externa, e um guard que nunca foi alcançado não aprovou esta chamada.',
    'hooks.http.deny_unanswered' => 'O hook HTTP `{hook}` não respondeu ({reason}); o alvo era {target}. Um hook que não pôde ser alcançado não aprovou esta chamada, então ela é recusada.',
    'hooks.http.deny_header_injection' => 'O hook HTTP `{hook}` não pode enviar seu cabeçalho `{field}`: o nome ou seu valor contém um caractere de controle, que é enquadramento de requisição em vez de valor de cabeçalho. Nada foi enviado a {target} e a chamada é recusada.',
    'hooks.http.notice_unanswered' => '⚠ O hook HTTP `{hook}` não respondeu ({reason}), então não pôde bloquear a chamada. Foi consultado em {target}.',
    'hooks.http.reason_unreachable' => 'a conexão ou a requisição expirou dentro do próprio timeout do hook',
    'hooks.http.reason_oversized' => 'a resposta foi maior que {bytes} bytes e não terminou',
    'hooks.http.reason_no_status' => 'a resposta não continha uma linha de status HTTP',
    'hooks.http.reason_redirect' => 'houve redirecionamento, e uma chamada de hook não segue redirecionamentos',
    'hooks.http.reason_status' => 'a resposta não foi um status 2xx',


    // --- C-EXT-6.d (type: prompt hooks) 2026-10-31 ---
    // Nothing was dialled and nothing was spent when these fire, so no row
    // carries a {target}: the hook either has no backend to be asked on, or
    // the answer it got is not a verdict.
    'hooks.prompt.deny_unanswered' => 'O hook de prompt `{hook}` não respondeu ({reason}). Um hook cujo veredito nunca foi retornado não aprovou esta chamada, então ela é recusada.',
    'hooks.prompt.notice_unanswered' => '⚠ O hook de prompt `{hook}` não respondeu ({reason}), então não pôde bloquear a chamada.',
    'hooks.prompt.reason_call_failed' => 'o modelo não pôde ser consultado',
    'hooks.prompt.reason_empty_verdict' => 'O hook de prompt `{hook}` negou esta chamada sem dar um motivo.',
    'hooks.prompt.reason_no_backend' => 'esta execução não tem um backend de título para consultar',
    'hooks.prompt.reason_no_prompt' => 'a entrada contém um prompt vazio para consultar',
    'hooks.prompt.reason_unparseable' => 'a resposta não foi o único objeto JSON com um booleano `ok` que é obrigatório',

    // --- settings help (W3-B i18n migration) ---
    'settings.advisorModel.help' => 'Modelo que a ferramenta `Advisor` consulta para uma segunda opinião; não definido — o padrão — não oferece a ferramenta (não há fallback para modelo barato: o ponto é um modelo que você escolheu).',
    'settings.allowedTools.help' => 'Lista de permissões de nomes de ferramentas ou globs; não definido oferece todas as ferramentas.',
    'settings.attribution.help' => '{"commit": "…", "pr": "…"}: o trailer e a linha de PR que a orientação de git solicita.',
    'settings.autoCommit.help' => 'off, turn (um commit por turno, mensagem do modelo de título) ou edit (um por Write/Edit); /undo reverte.',
    // C-SEC-7.e (owner ruling t212, option 3): the help states the implicit
    // default, the once-per-session announce, and the paid-call fact.
    'settings.autoReview.help' => 'Em auto, uma chamada sinalizada pelo classificador de segurança (exceto uma descoberta de segurança, que sempre pergunta) é revisada pelo modelo de título, que a permite, pergunta a você ou a nega. Ativado por padrão sempre que existe um modelo revisável, e uma execução que ativa esse padrão informa uma vez; defina false para desativar. Cada revisão é uma chamada de modelo paga.',
    'settings.autoReviewModel.help' => 'O `provider/model` no qual o revisor automático roda, por exemplo `openai/gpt-4.1-mini`; vazio significa o modelo de título. Um provedor que não pode ser construído deixa o revisor desativado com um aviso de execução.',
    'settings.autoReviewScope.help' => 'O que `autoReview` envia ao revisor: `shell` (o padrão) é todo comando de shell não somente-leitura que a lista de padrões passou; `writes` também revisa `Edit`, `Write`, `ApplyPatch` e `WebFetch`, com o diff pendente para as ferramentas de escrita; `all` revisa toda chamada que a lista passou. Qualquer outra grafia se comporta como `shell`. Cada revisão é uma chamada de modelo paga.',
    'settings.autoTest.help' => 'Após um turno que editou um arquivo, execute `testCommand`; em caso de falha, a saída volta ao modelo, no máximo 3 vezes por turno.',
    'settings.bashInteractiveIdleSeconds.help' => 'Segundos que uma execução Bash com `interactive: true` pode não imprimir nada antes de ser parada por estar aguardando uma tecla.',
    'settings.bashMaxTimeoutSeconds.help' => 'O maior `timeout` que um comando Bash pode solicitar; valores maiores são limitados a ele.',
    'settings.bashSandbox.help' => 'Linux executa Bash dentro do bubblewrap; macOS executa dentro de um perfil Seatbelt via `sandbox-exec` — gravável apenas na raiz de trabalho (`no-network` também corta a rede). `allowlist` (Linux) roteia o tráfego de saída pela rede do proxy de saída da execução, que concede apenas os hosts listados em `sandboxAllowedDomains`: com a lista vazia padrão, comporta-se EXATAMENTE como `no-network` até que você liste hosts, e mesmo depois de listados, tráfego não-HTTP (ssh, portas de banco de dados) e qualquer host não listado falham. No macOS, `allowlist` é aplicado como `no-network`. Recusa comandos quando a jaula não pode iniciar; um valor não reconhecido significa `no-network`, nunca `off`.',
    'settings.bashSandboxNestedUserns.help' => 'Defina `true` para permitir que um comando `Bash` em sandbox crie seu próprio namespace de usuário, o que é necessário para podman ou buildah rootless e uma sandbox do Chromium. O padrão `false` executa bubblewrap com `--unshare-user --disable-userns`, bloqueando o caminho usual de volta para fora de uma jaula de montagem; em um host cujo bubblewrap é muito antigo para essas flags, a jaula executa o conjunto simples e sua própria descrição informa isso.',
    'settings.bashTimeoutSeconds.help' => 'Segundos que um comando Bash pode executar quando o modelo não passa um `timeout`; nunca acima do teto do Bash.',
    'settings.chatToolTimeoutSeconds.help' => 'Orçamento de tempo real de um lote de chamadas de ferramentas que o caminho nativo de chat (provedor `command`) bifurca; os retardatários são mortos.',
    'settings.claudeMcpArgs.help' => 'Argumentos para esse binário; não definido usa o padrão do transporte.',
    'settings.claudeMcpBinary.help' => 'Caminho absoluto do binário `claude` que o transporte claude-mcp pode iniciar.',
    'settings.claudeMcpEnv.help' => 'Variáveis de ambiente literais passadas a esse binário.',
    'settings.compaction.autoPercent.help' => 'Fração da janela na qual trocas antigas são condensadas automaticamente antes do prompt ser enviado.',
    'settings.compaction.autoTokens.help' => 'Teto absoluto no nível automático e no orçamento de passos por turno. 0 desativa o teto.',
    'settings.compaction.blockPercent.help' => 'Fração da janela além da qual um prompt é recusado até que espaço seja liberado; o único nível que recusa.',
    'settings.compaction.blockTokens.help' => 'Teto absoluto no nível de bloqueio; não definido por padrão. Definir permite que um teto recuse prompts.',
    'settings.compaction.idleAuto.help' => 'Compactar uma sessão ociosa acima do nível durante a ociosidade em vez de esperar pelo próximo prompt, usando a mecânica do nível automático (teto de gasto e quebra de thrash se aplicam). off: nunca; hour: após a janela completa de compaction.idleOfferSeconds; cacheTtl: pouco antes da expiração do prompt-cache do provedor — uma hora quando o provedor marca pontos de cache, cerca de 5 min para caches no servidor, nunca onde ele não reporta nada em cache — uma vez que o histórico está acima de um piso abaixo do nível automático, porque o próximo prompt pré-preencheria toda a conversa sem cache; no tick de 60 segundos, um cache de 5 min se dobra em aproximadamente 4 minutos de ociosidade. Custa uma chamada de provedor em segundo plano; precisa de compaction.idleOfferSeconds acima de 0. Um bool continua sendo lido: true significa hour, false significa off.',
    'settings.compaction.idleOfferSeconds.help' => 'Uma sessão além de toda a sua janela de contexto que ficou intocada por esse tempo recebe a oferta de /compact em vez de enviar o prompt. 0 nunca oferece.',
    'settings.compaction.keepRecent.help' => 'Trocas mais recentes de usuário/assistente que uma compactação mantém por completo.',
    'settings.compaction.mode.help' => 'llm: o modelo de resumo escreve os resumos (a heurística é seu fallback); heuristic: resumos locais de uma linha, nunca uma chamada de modelo; off: nada compacta por conta própria, /compact ainda funciona e o nível de bloqueio ainda recusa.',
    'settings.compaction.modelTokenCaps.help' => '{"<model>" ou "<provider>/<model>": {"reminderTokens", "autoTokens", "blockTokens"}} substituindo os três tetos; 0 limpa um.',
    'settings.compaction.refillLimit.help' => 'Compactações automáticas em sequência que podem voltar diretamente acima de seu nível, com o prompt não enviado, antes que o próximo prompt seja recusado em vez de compactado novamente.',
    'settings.compaction.reminderPercent.help' => 'Fração da janela na qual o lembrete "consider compacting" e o resumo em segundo plano antecipado começam; abaixo do nível automático.',
    'settings.compaction.reminderTokens.help' => 'Teto absoluto no nível de lembrete: dispara em min(percentage, this). 0 desativa o teto.',
    'settings.compaction.summaryAssistantChars.help' => 'Respostas do assistente mais longas que isso se tornam "[exchanged information]" em uma linha de resumo heurística.',
    'settings.compaction.summaryUserChars.help' => 'Caracteres de uma mensagem de usuário que a linha de resumo heurística mantém.',
    'settings.compaction.toolOutputChars.help' => 'Caracteres da metade assistente de uma troca condensada que o modelo de resumo recebe.',
    'settings.connectTimeoutSeconds.help' => 'Limite para alcançar um host do provedor (DNS, TCP, TLS); não é um timeout de requisição.',
    'settings.contextPruning.compress.help' => 'manual oferece Compress apenas em um turno iniciado com /compress, uma chamada; auto oferece em todo turno em que o modelo pode podar.',
    'settings.contextPruning.iterationNudgeThreshold.help' => 'Resultados de ferramentas desde o último prompt após os quais um longo loop de ferramentas é lembrado de podar.',
    'settings.contextPruning.maxContextTokens.help' => 'Tamanho de contexto acima do qual a linha mais recente carrega o lembrete mais forte "prune now".',
    'settings.contextPruning.minContextTokens.help' => 'Tamanho de contexto abaixo do qual o modelo nunca é lembrado de podar; não deve exceder o tamanho do lembrete rígido.',
    'settings.contextPruning.mode.help' => 'auto poda linhas substituídas no início de cada turno; manual apenas em /sweep; off não mostra tags de referência. /pruning substitui por sessão.',
    'settings.contextPruning.nudgeFrequency.help' => 'Novas linhas que um lembrete espera após o último, para não se repetir a cada passo.',
    'settings.contextWindow.help' => 'Substituição da janela de tokens: uma contagem para o modelo do provedor, ou {"<model>": tokens}.',
    'settings.debug.commands.help' => 'Coloque cada diretório ou arquivo de comando personalizado recusado no stderr, não apenas a contagem de uma linha da execução.',
    'settings.debug.rules.help' => 'Coloque cada diretório ou arquivo de regras recusado no stderr.',
    'settings.debug.skills.help' => 'Coloque cada arquivo de skill pulado e diretório de skills recusado no stderr, não apenas a contagem de uma linha da execução.',
    'settings.debug.stream.help' => 'Coloque a linha "onToken observer threw, detaching it" no stderr quando o sink de streaming de um embedder falha no meio de um turno.',
    'settings.diffPreviewRows.help' => 'Linhas de um diff de Edit ou Write mostradas na transcrição antes que o resto seja resumido.',
    'settings.diffStyle.help' => 'Layout de diff na transcrição: `auto` pinta hunks lado a lado em terminais largos (120 colunas ou mais) e unificado nos demais, `unified` sempre uma coluna, `split` sempre duas. Corpos de diff são coloridos por token em qualquer layout; a coluna de marcadores `+`/`-` mantém sua cor.',
    'settings.disabledMcpServers.help' => 'Nomes de servidores ou globs do `.mcp.json` (`untrusted_*`) que nunca são iniciados, listados ou chamados, para o agente principal e cada sub-agente.',
    'settings.disabledRules.help' => 'Pacotes de regras de nível de usuário mantidos fora do prompt desde o primeiro turno.',
    'settings.disabledSkills.help' => 'Skills removidas da descoberta; também prevalece sobre enabledSkills.',
    'settings.disabledTools.help' => 'Nomes de ferramentas ou globs removidos do conjunto de ferramentas voltado ao modelo.',
    'settings.doubleEscSeconds.help' => 'Com que rapidez o segundo Esc deve seguir o primeiro para cancelar um turno em execução.',
    'settings.embeddingModel.help' => 'Modelo de embedding para a recuperação de memória por turno; não definido classifica notas apenas por palavra-chave.',
    'settings.enabledSkills.help' => 'Skills cujos corpos completos acompanham o prompt de sistema a cada turno.',
    'settings.env.diffMaxBytes.help' => 'Bytes que cada uma das duas seções de diff git mantém antes de ser truncada com uma nota.',
    'settings.env.gitDiffAfterWrites.help' => 'Após um passo que escreveu arquivos, mostre os diffs git staged e unstaged no contexto do turno.',
    'settings.expandToolOutput.help' => 'Mostre a saída completa de cada chamada de ferramenta concluída na transcrição; Ctrl+O ou um clique ainda colapsa uma.',
    'settings.extraBody.help' => 'Campos de requisição de nível superior adicionados a toda requisição de provedor `custom`.',
    'settings.formatCommands.help' => 'Comando de formatação pós-edição por extensão de arquivo ({"php": "vendor/bin/php-cs-fixer fix {file}"}); roda antes do lint pós-edição e reescreve o arquivo. Desativado por padrão.',
    'settings.formatAuto.help' => 'Permita que a tabela de extensões embutida (gofmt, rustfmt, ruff/black, shfmt, terraform fmt, o prettier do node_modules do próprio projeto) formate um arquivo editado quando `formatCommands` não nomeia um comando para sua extensão. Entradas explícitas prevalecem; um projeto ainda precisa de `trustedProjectHooks`. Desativado por padrão.',
    'settings.globMaxMatches.help' => 'Caminhos que um Glob coleta antes de sua varredura parar; o teto de saída ainda limita o resultado.',
    'settings.grepTimeoutSeconds.help' => 'Segundos que uma busca Grep pode executar antes de ser morta; resultados encontrados até o prazo voltam como resultado parcial.',
    'settings.hooksDefaultTimeoutSeconds.help' => 'Segundos que uma entrada de hook sem `timeout:` pode executar antes de ser morta e contada como recusa.',
    'settings.includeGitInstructions.help' => 'Se a orientação genérica de commit da ferramenta Bash acompanha o prompt de sistema.',
    'settings.instructions.help' => 'Globs de arquivos cujo conteúdo se torna texto autoritativo do prompt de sistema.',
    'settings.instructions.walkToRoot.help' => 'Opt-in: também leia arquivos de instrução acima do marcador .git mais próximo, até mas sem incluir o diretório home. Apenas nível de usuário; cada leitura mantém seu orçamento de contenção e tamanho.',
    'settings.instructionsExclude.help' => 'Globs de arquivos de instrução a pular, registrados como recusas; apenas nível de usuário — um repositório não pode silenciar seu operador. Arquivos dentro do checkout correspondem por caminho relativo ao checkout; arquivos ancestrais e forçados fora dele correspondem por caminho absoluto, então `**/CLAUDE.local.md` alcança as cópias ancestrais também.',
    'settings.keybindings.help' => '{"shell.palette": "Ctrl+B"}: vincule um acorde EXTRA a um id de binding (a referência /keys os nomeia) — Ctrl+<key>, Alt+<key>, Shift+<key>, ou uma tecla de função isolada; o acorde padrão continua funcionando. Presente-mas-inutilizável recusa a execução; remova a tecla para os bindings padrão.',
    'settings.layout.help' => 'O manifesto de painéis acoplados; escrito pelo shell quando painéis se movem.',
    'settings.lintCommands.help' => 'Comando de lint pós-edição por extensão de arquivo ({"php": "…", "js": false}); `php -l` é embutido.',
    'settings.lsp.help' => '{"php": {"command": "intelephense", "args": ["--stdio"]}}: servidores para diagnósticos pós-edição, outlines de Read e a ferramenta Lsp.',
    'settings.lspAutoDetect.help' => 'Inicie o servidor de linguagem que a impressão digital do projeto nomeia (composer.json → intelephense, package.json + tsconfig.json → typescript-language-server, pyproject.toml ou setup.py → pyright-langserver, go.mod → gopls, Cargo.toml → rust-analyzer) quando seu binário está no PATH; entradas `lsp` manuais prevalecem por linguagem. Iniciar um servidor executa esse servidor e o código de build na árvore aberta, então impressões digitais iniciam servidores apenas em projetos que você confiou para hooks; uma raiz não confiada não inicia nenhum e registra o pulo nos avisos de execução.',
    'settings.maxCheckpoints.help' => 'Checkpoints de turno que /rewind pode retornar, por sessão; os mais antigos são podados além deste.',
    'settings.maxCostUsd.help' => 'Recuse novos turnos quando o gasto reportado pelo provedor de uma execução atingir esse valor em dólares; não definido é sem teto. /budget altera apenas para a execução em andamento.',
    'settings.maxOutputTokens.help' => 'Limite de saída por requisição; sem definição não envia substituição e o padrão do provedor se aplica.',
    'settings.maxToolSteps.help' => 'Chamadas ao provedor que um turno pode fazer; sem definição mantém o padrão do motor.',
    'settings.mcp.enabled.help' => 'Inicia os servidores MCP listados no .mcp.json de um projeto confiável; off não inicia nenhum e as superfícies reportam o lançamento como desabilitado.',
    'settings.mcp.lazySchemaTokens.help' => 'Tokens de esquema que um servidor MCP pode anunciar antes de suas ferramentas delegarem a mcp_list/mcp_call; 0 nunca delega.',
    'settings.mcpResultCapBytes.help' => 'Máximo de bytes que a resposta de uma ferramenta MCP pode entregar ao modelo.',
    'settings.memory.autoConsolidate.help' => 'Salva fatos duráveis de turnos concluídos na memória e incorpora o diário de compactação a ela (a passada de sonho); cada uma é uma chamada cobrada.',
    'settings.memory.dreamIntervalSeconds.help' => 'Tempo mínimo entre duas passadas de sonho para um projeto; cada passada é um turno somente-leitura cobrado.',
    'settings.memory.dreamProposeSkills.help' => 'Permite que a passada de sonho proponha habilidades como rascunhos em ~/.candy-code/skills-proposed; nenhuma fica ativa até você aceitar com /skills.',
    'settings.memory.entryMaxBytes.help' => 'Comprimento máximo da linha de índice de uma nota antes de ser exibida truncada; reduzido ao orçamento de notas do usuário se excedido.',
    'settings.memory.projectNoteMaxBytes.help' => 'Tamanho máximo de uma nota de memória do projeto ao ser escrita em .candy-code/memory/ do repositório.',
    'settings.memory.promptMaxBytes.help' => 'Orçamento de bytes para as linhas de notas do índice de memória; o orçamento de notas do usuário é reduzido para caber nele.',
    'settings.memory.promptMaxEntries.help' => 'Máximo de notas que o índice de memória do prompt lista, mais recentes primeiro; notas do usuário contam dentro dele.',
    'settings.memory.userMaxBytes.help' => 'Orçamento de bytes para linhas de escopo do usuário, dentro do orçamento total.',
    'settings.memory.userMaxEntries.help' => 'Máximo de notas entre projetos (escopo do usuário) listadas primeiro, dentro da contagem de notas.',
    'settings.modelPrices.help' => 'USD por 1M de tokens por modelo ({"input": …, "output": …}), para o total e limite de gastos.',
    'settings.models.help' => 'O modelo a executar, por provedor ({"<provider>": "<model id>"}); sem definição usa o padrão do provedor.',
    'settings.mouse.help' => 'Reporta o mouse ao candy-code (cliques, roda, seleção); off devolve ao terminal o próprio copiar-ao-selecionar.',
    'settings.mouseClicks.help' => 'Cliques e arrastos atuam sobre o que atingem; off mantém a roda e ignora cliques.',
    'settings.notices.transcriptLimit.help' => 'Máximo de avisos de lançamento exibidos como linhas do transcript; os demais são contados em uma linha "e mais N", e stderr carrega todos.',
    'settings.notify.help' => 'off, bell (BEL) ou osc9 (uma notificação de desktop): enviada quando um turno termina e quando o agente aguarda uma aprovação.',
    'settings.paletteMru.help' => 'Quantas linhas de paleta usadas recentemente são lembradas e classificadas primeiro; 0 não lembra nenhuma.',
    'settings.parallelToolCalls.help' => 'Executa chamadas de ferramentas somente-leitura de um turno em paralelo.',
    'settings.parallelToolDeadlineSeconds.help' => 'Limite de tempo real para um lote de chamadas de ferramentas despachadas em paralelo.',
    'settings.permissionMode.help' => 'Como as chamadas de ferramentas são controladas. Nunca obtido de um arquivo de projeto.',
    'settings.permissionRules.help' => 'Regras ordenadas allow / deny / ask comparadas com cada chamada de ferramenta. Um settings.json compartilhado de projeto confiável pode contribuir com entradas deny / ask — apenas restringindo.',
    'settings.permissions.autoAllowReadOnly.help' => 'Sob default e accept-edits, executa uma linha Bash feita apenas de comandos somente-leitura (ls, cat, grep, git log, …; sem redirecionamento de arquivo, sem substituição, cd apenas dentro do projeto) sem perguntar. Um projeto só pode desativá-la.',
    'settings.permissions.autoStrikeLimit.help' => 'Sob auto, este número de chamadas bloqueadas de uma categoria em sequência transforma a próxima em uma pergunta.',
    'settings.permissions.autoTotalLimit.help' => 'Sob auto, após este número de chamadas bloqueadas em uma sessão, cada bloqueio adicional pergunta a você.',
    'settings.pluginPaths.help' => 'Diretórios adicionais escaneados para pacotes de plugins no formato Claude, além das duas raízes instaladas; um valor pode nomear um pacote em si ou um contêiner de pacotes. Apenas nível de usuário — um checkout não pode inscrever seus próprios plugins.',
    'settings.promptCache.keepWarm.help' => 'Pings de aquecimento permitidos por período de inatividade; 0 (padrão) é desligado. Cada ping reenvia o prefixo congelado de uma sessão inativa com uma linha de instrução pedindo uma resposta de um caractere, para que o provedor renove seu cache de prompt antes que o TTL expire e o próximo prompt não prefira toda a conversa sem cache. Dispara apenas onde a dobra cacheTtl recusou — abaixo do piso ou antes da hora — no mesmo tick/alarme que a vigília da dobra já executa, nunca no meio de um turno, nunca mais de um por vez, nunca além desta contagem por período. São chamadas cobradas a uma sessão que ninguém está observando; o limite de gastos ainda se aplica. A contagem aparece em /usage sob `warm`.',
    'settings.promptCache.help' => 'Se os provedores `vertex` e `bedrock` marcam pontos de quebra de cache de prompt.',
    'settings.promptSuggestionHistory.help' => 'Mensagens recentes (cada uma cortada a 2000 caracteres) exibidas na chamada de sugestão de prompt.',
    'settings.promptSuggestions.help' => 'Após cada turno, pergunta ao modelo de título a mensagem que você provavelmente enviará em seguida e a exibe em cinza na caixa de entrada vazia (→ aceita).',
    'settings.provider.help' => 'Qual provedor LLM a sessão utiliza; cada prompt é enviado ao seu host.',
    'settings.providerRetryAttempts.help' => 'Chamadas por requisição ao provedor quando falha transitoriamente (rede, 5xx, 408, 429), incluindo a primeira; 1 nunca tenta novamente.',
    'settings.providerRetryBaseBackoffMs.help' => 'Espera antes da primeira tentativa de uma chamada ao provedor que falhou; cada espera subsequente dobra.',
    'settings.providers.help' => 'Definições de provedor por nome ({"<name>": {"type": …, "baseUrl": …, "apiKey": …, "model": …}}); cada entrada se sobrepõe aos padrões daquele tipo. Apenas nível de usuário: um projeto nunca deve alterar para onde sua credencial é enviada.',
    'settings.queueMode.help' => 'steer (o agente lê no próximo passo), followup (enviado após o turno) ou interrupt (para o turno no próximo passo e envia). Tab sempre enfileira.',
    'settings.readMaxBytes.help' => 'Limite de uma chamada Read; a página abaixo é o tamanho que uma leitura geralmente retorna.',
    'settings.readPageBytes.help' => 'Bytes que uma página Read pode conter, incluindo números de linha, independentemente do que `limit` pedir.',
    'settings.readPageLines.help' => 'Linhas que um Read retorna quando a chamada não especifica `limit`.',
    'settings.reasoningEffort.help' => 'Nível de raciocínio enviado onde o par o molda: openai (série o e gpt-5, não as builds -chat), anthropic e vertex (claude-3-7 e mais recentes; vertex responde em ambos os braços claude e gemini), gemini (2.5 e mais recentes), sglang (encaminhado em toda requisição), bedrock (ids claude, como orçamento de raciocínio), codex e claude-code (níveis nomeados encaminhados ao CLI); sem definição ou não reconhecido não solicita nada. `/effort` define e limpa.',
    'settings.redactToolOutput.help' => 'Desligado por padrão: a saída de ferramentas consolidada é salva no histórico e sessions.db exatamente como retornou. Quando ligado, cada resultado de ferramenta passa pelo mesmo redator que protege memória e `/share` após se consolidar — credenciais reconhecidas viram `[REDACTED]` nos bytes que persistem e no que turnos posteriores reproduzem ao modelo (a ferramenta em si ainda executa inalterada). Campos de imagem, documento e uso passam intactos. `/export` não adiciona redação própria: imprime exatamente o que foi armazenado, então qualquer coisa salva antes de ativar isto permanece bruta.',
    'settings.references.help' => 'Uma lista de `[{"path": "…", "name": "…"}]` de diretórios fora do workspace que Read, Grep, Glob e Ls também podem abrir, somente-leitura; cada um é anunciado no bloco `<env>` com um mapa limitado do que há nele. A jaula do workspace é inalterada para Write, Edit e Bash — uma referência nunca amplia o que pode ser escrito. Apenas nível de usuário: um repositório checkout não pode adicionar uma raiz de leitura. Um caminho inexistente ou não-diretório, ou dentro da raiz da sessão, é recusado no lançamento com um aviso.',
    'settings.repoMap.enabled.help' => 'Coloca o mapa de onde o código reside (pacotes e diretórios de origem PSR-4) no prompt do sistema.',
    'settings.repoMap.maxBytes.help' => 'Orçamento de bytes para cada uma das duas seções do mapa do repositório; entradas além dele são contadas, não listadas.',
    'settings.requireReadBeforeWrite.help' => 'On, `Edit`, um `Write` que sobrescreve um arquivo existente, e uma seção `ApplyPatch` que altera, move ou exclui um arquivo recusam até que o modelo tenha lido aquele arquivo nesta sessão; criar arquivos novos nunca é bloqueado. Desligado por padrão: arquivos que o modelo leu permanecem protegidos pela regra de alterado-em-disco de qualquer forma.',
    'settings.resumeCostWarnUsd.help' => 'Após um resume obsoleto, o primeiro prompt é retido uma vez quando reenviar o histórico é estimado em custar pelo menos este valor em dólares sem cache; pressione Enter novamente para enviar mesmo assim, ou /compact antes. 0 desativa a retenção.',
    'settings.sandboxAllowedDomains.help' => 'Os hosts que a jaula `allowlist` pode alcançar: nomes simples (`example.com`), curingas `*.example.com` e grafias `host:porta` (padrão: nada). Usado apenas quando `bashSandbox` é `allowlist` no Linux; com uma lista VAZIA `allowlist` se comporta EXATAMENTE como `no-network`. O proxy de saída concede HTTP(S) e nada mais — todo host não listado recebe 403, e tráfego não-HTTP (ssh, portas de banco de dados) falha. Uma entrada malformada é IGNORADA na aplicação: um erro de digitação só pode reduzir a concessão, nunca ampliá-la. Apenas nível de usuário: um repositório checkout não deve abrir um buraco na jaula em que chegou. macOS aplica `allowlist` como `no-network` — o braço de porta de loopback é um acompanhamento rastreado.',
    'settings.sandboxScope.help' => 'Quais comandos fora do caminho da ferramenta entram na jaula `bashSandbox`: `hooks`, `lint`, `format`, `test`, `lsp`, `mcp` (padrão: nenhum). Ativo apenas enquanto `bashSandbox` não é `off` — a lista diz quem compartilha a jaula, nunca se uma existe. Uma entrada não reconhecida lê como TODO escopo (mais restrito, como um valor `bashSandbox` não reconhecido), e a auditoria de configurações o nomeia. Uma jaula que não pode iniciar recusa o trabalho em vez de executá-lo livre: hooks de script negam, lint, format e test pulam com o motivo, e um servidor LSP ou MCP stdio enjaulado não é iniciado. Entradas `lsp` e entradas MCP de nível de usuário carregam uma exclusão por servidor `"sandbox": false`; exclusões MCP de nível de projeto são ignoradas.',
    'settings.screenReader.help' => 'Apresentação para usuários de leitor de tela. On, o app elimina decoração que um leitor não pode narrar — o spinner do agente fixa em um quadro estático, e molduras de desenho de caixa, seleção de menu em vídeo-reverso e similares dão lugar a texto simples e um sinal audível conforme cada superfície honra a mudança. Off é o terminal pintado como de costume. Sua própria configuração de acessibilidade, como o modo vim da caixa de rascunho: um projeto checkout não pode alterá-la. Aplica na próxima leitura após salvar — ao vivo, sem recarregar.',
    'settings.rules.standingMaxBytes.help' => 'Orçamento de bytes, emoldurado e escapado, para os arquivos de regra inseridos inteiros em cada prompt; uma regra além dele é nomeada por uma linha de ponteiro em vez disso.',
    'settings.scrollWheelLines.help' => 'Linhas do transcript que um clique da roda rola.',
    'settings.sd.apiKey.help' => 'Chave Bearer enviada ao servidor Stable Diffusion, se ele exigir uma; prefira a forma de placeholder `${VAR}` sobre um literal.',
    'settings.sd.baseUrl.help' => 'URL base HTTP de um webui Stable Diffusion compatível com AUTOMATIC1111 (`http://127.0.0.1:7860`); prompts, imagens e a chave de API todos saem por ali.',
    'settings.sd.defaultModel.help' => 'Id de modelo com que as requisições de geração começam; o servidor mantém a escolha para si quando não definido.',
    'settings.sd.presets.help' => 'Conjuntos de parâmetros nomeados que o formulário de mídia oferece; o formato é próprio do pipeline de mídia, opaco à camada de configurações.',
    'settings.sd.savePattern.help' => 'Modelo de nome de arquivo para mídia salva; os tokens `[date]`, `[time]`, `[seed]` e `[number]` são preenchidos no momento de salvar.',
    'settings.sd.timeoutSeconds.help' => 'Segundos que uma requisição de geração pode executar antes de ser abandonada; difusão em uma GPU fraca rotineiramente leva minutos.',
    'settings.secretEnvAllowlist.help' => 'Nomes de variáveis com formato de credencial (ou globs) que Bash, Grep e hooks de script ainda herdam.',
    'settings.server.allowBypass.help' => 'Se sessões do servidor podem executar em bypass-permissions ou dont-ask (mesmo que --allow-bypass).',
    'settings.server.allowedHosts.help' => 'Nomes de host (ou host:porta) aos quais o servidor responde, além dos nomes de loopback e seus próprios endereços, ex.: de um proxy reverso.',
    'settings.server.allowedIps.help' => 'IPs de cliente ou faixas CIDR permitidos para conectar, além de loopback; qualquer outro recebe 403 antes do login. Vazio: sem filtro de endereço.',
    'settings.server.allowedOrigins.help' => 'Origens de navegador extras (http(s)://host[:porta]) que o servidor aceita, além das suas.',
    'settings.server.askTimeoutSeconds.help' => 'Segundos que uma pergunta de permissão aguarda um cliente antes de ser recusada; 0 espera para sempre.',
    'settings.server.browseRoot.help' => 'O diretório ao qual server.dirBrowse está confinado (mesmo que --browse-root); sem definição é seu diretório home.',
    'settings.server.dirBrowse.help' => 'Permite que clientes autenticados listem nomes de diretórios sob server.browseRoot e iniciem sessões ali (mesmo que --allow-dir-browse). Desligado por padrão.',
    'settings.server.clientTools.help' => 'Permite que clientes de escopo Write registrem ferramentas via tools.client.register para que o modelo possa chamar código que executa no próprio cliente (ferramentas client__*). Desligado por padrão.',
    'settings.server.drainSeconds.help' => 'Segundos que um servidor em parada aguarda pelos turnos em execução antes de cancelá-los; 0 interrompe imediatamente.',
    'settings.server.host.help' => 'O endereço ao qual `serve` se vincula. Qualquer coisa que não seja loopback também precisa de --allow-remote na inicialização.',
    'settings.server.maxConcurrentTurns.help' => 'Turnos que um servidor executa simultaneamente em suas sessões; um a mais é recusado como ocupado (retentável).',
    'settings.server.maxOpenSessions.help' => 'Sessões que um servidor mantém abertas simultaneamente; ao ultrapassá-lo, a sessão ociosa menos usada recentemente é liberada.',
    'settings.server.port.help' => 'A porta que o `serve` vincula; 0 escolhe uma livre.',
    'settings.server.trustedProxies.help' => 'IPs ou CIDRs em que o servidor confia para X-Forwarded-For / X-Forwarded-Proto.',
    'settings.serviceTier.help' => 'Faixa premium enviada onde o par a define: openai solicita `service_tier: "priority"` em ambas as ramificações Chat e Responses, anthropic solicita `speed: "fast"` (apenas na família claude-opus-5-5 GA e nas famílias research-preview claude-opus-5 / claude-opus-4-8, cujo cabeçalho beta obrigatório é enviado automaticamente); não definido ou não reconhecido não solicita nada. O modo Fast cobra um premium que nenhuma tabela de preços por modelo consegue derivar: enquanto um par com tiers está ativo, seus turnos entram no livro-razão sem preço, nunca como uma taxa estimada. Aplica-se no lançamento e a cada reconstrução de provedor ou modelo.',
    'settings.sessionRetentionDays.help' => 'Cada execução exclui sessões sem nome e sem fixação inativas por esse número de dias e informa quais; 0 (padrão) mantém tudo.',
    'settings.sessions.autoTitle.help' => 'Nomeia cada nova sessão a partir da primeira interação com uma chamada ao modelo de título; desativado deixa sem nome até /rename.',
    'settings.sessions.awayRecap.help' => 'Quando o terminal reportar o retorno de foco após você ter ficado ausente por três minutos ou mais, imprima um resumo de onde a sessão parou (uma chamada ao modelo de título por ausência); off deixa o retorno silencioso. `/recap` solicita um a qualquer momento.',
    'settings.skills.listingMaxBytes.help' => 'Orçamento de bytes para a listagem completa de skills no prompt do sistema; skills além desse limite se resumem em uma linha "N more skills".',
    'settings.skills.pathNudges.help' => 'Quando uma ferramenta acessar um arquivo coberto por uma habilidade com escopo de caminho, lembre o modelo de que essa habilidade existe, uma vez por habilidade.',
    'settings.statusLine.help' => '{"type": "command", "command": "…", "refreshSeconds": 2}: um comando de shell cuja saída pinta a barra de status, reexecutado a cada refreshSeconds (2 a 3600, padrão 2). Ele recebe a sessão como um documento JSON no stdin (session_id, cwd, model, workspace, version, cost, além de extras candy_code); um comando que nunca lê o stdin ainda é executado.',
    'settings.streamHeaderTimeoutSeconds.help' => 'Segundos que um servidor de streaming conectado pode levar para enviar seus cabeçalhos de resposta; nunca um timeout total da requisição.',
    'settings.streamIdleTimeoutSeconds.help' => 'Segundos que uma leitura de resposta em streaming pode aguardar bytes antes de a conexão ser considerada morta; por leitura, nunca total.',
    'settings.subagentMaxActive.help' => 'Execuções delegadas que uma sessão pode ter simultaneamente, contando cada nível, membro e agente em segundo plano; acima disso, uma chamada `Task` é recusada. Não definido — o padrão — ou 0 não impõe limite.',
    'settings.subagentMaxConcurrent.help' => 'Chamadas de `Task` de um lote que executam simultaneamente (as demais aguardam uma vaga livre), e a largura de cada pool de agentes. Não definido — o padrão — ou 0 não impõe limite.',
    'settings.subagentMaxDepth.help' => 'Níveis abaixo da sessão em que uma execução delegada pode estar; uma execução no último nível não recebe `Task`. 1 impede que sub-agentes deleguem ainda mais.',
    'settings.subagentMaxTurns.help' => 'Limite de etapas para um subagente — uma delegação de `Task`, um estágio de workflow ou uma execução de `executeAgents` — cujo preset não declara `maxTurns`.',
    'settings.subagentModel.help' => 'Modelo em que um sub-agente delegado é executado quando sua predefinição diz `inherit`; não definido segue o modelo da sessão.',
    'settings.summaryModel.help' => 'Modelo que escreve resumos de compactação; não definido usa o próprio modelo da conversa, que reutiliza o cache de prompt.',
    'settings.symbolMap.enabled.help' => 'Inserir o mapa do repositório por símbolos, classificado, no prompt do sistema, capturado uma vez por sessão.',
    'settings.temperature.help' => 'Temperatura de amostragem que o provedor `custom` envia quando uma solicitação não especifica nenhuma.',
    'settings.terminalBackground.help' => 'O que o tema adaptativo assume por trás do texto: auto consulta o terminal (OSC 11, depois COLORFGBG); light ou dark declara diretamente.',
    'settings.testCommand.help' => 'Comando de shell que executa os testes do projeto, na raiz do projeto (`composer test`, `pytest -q`); o que `autoTest` executa.',
    'settings.theme.help' => 'Tema de cores; /theme e a paleta alteram ao vivo. Temas personalizados carregam de arquivos JSON em ~/.candy-code/themes.',
    'settings.thinkingBudget.help' => 'Orçamento de tokens de raciocínio: `thinkingConfig` do Gemini no provedor `vertex`; raciocínio estendido no provedor `anthropic`, onde o mínimo da Messages API é 1024 (0 ou não definido significa desligado em ambos os casos). Tokens de raciocínio são cobrados como saída.',
    'settings.titleModel.help' => 'Modelo que nomeia sessões e escreve sugestões de prompt; não definido usa o padrão auxiliar barato do tipo de provedor antes do modelo principal.',
    'settings.transcriptJsonl.help' => 'Espelhar cada transcrição confirmada em um diário JSONL somente de acréscimo em `~/.candy-code/transcripts/<project>/` (arquivos 0600), e fornecer aos scripts de hook uma chave `transcript_path` no stdin apontando para ele. O diário contém a conversa bruta e cresce sem limite; lido no início, então uma alteração se aplica no próximo start.',
    'settings.toolInstructionCapBytes.help' => 'Máximo de bytes do corpo de um CLAUDE.md/AGENTS.md que um resultado de Edit, Write ou ApplyPatch pode carregar; o restante é cortado com um marcador.',
    'settings.toolOutputCapBytes.help' => 'Máximo de bytes que um resultado de Bash, Grep, Glob, Lsp ou WebFetch pode entregar ao modelo; o que é cortado é salvo em um arquivo que o resultado nomeia.',
    'settings.toolOutputPreviewLines.help' => 'Linhas de um resultado de ferramenta colapsado exibidas na transcrição; Ctrl+O expande o restante.',
    'settings.toolSpillCaptureBytes.help' => 'Máximo da saída de um comando Bash (por stream) mantido em memória e salvo no arquivo de despejo quando o resultado é cortado; nunca abaixo do limite de saída.',
    'settings.toolSpillMinCapBytes.help' => 'Menor limite de resultado em que um resultado de ferramenta cortado é salvo em arquivo; abaixo dele, o corte é anunciado e o restante descartado.',
    'settings.toolSpillWindowPercent.help' => 'Maior fração da janela de contexto que um resultado de ferramenta pode ocupar; além dela, o resultado é salvo em arquivo e o modelo vê o início e o fim.',
    'settings.trustedProjectCommands.help' => 'Raízes de projeto cujos comandos de barra podem executar blocos de shell !`cmd`.',
    'settings.trustedBundleCommands.label' => 'Comandos de bundle confiáveis',
    'settings.trustedBundleCommands.help' => 'Nomes de bundles de plugin cujos arquivos de comando podem executar blocos de shell !`cmd`; cada comando ainda é julgado pelo portão de permissões. Os nomes correspondem ao nome do manifesto do próprio bundle, e somente instalações em nível de usuário contam — um checkout de projeto não pode conceder shell a si mesmo, nem mesmo usurpando um nome listado. Optar não é um contorno: no portão apenas uma regra Deny recusa, e uma regra que o portão avalia como Ask executa sem supervisão — a expansão não tem prompt para exibir. Vazio por padrão, então comandos de bundle não executam shell.',
    'settings.mcpPromptShell.label' => 'Shell de prompt MCP',
    'settings.mcpPromptShell.help' => 'Chaves de servidores MCP cujos corpos de prompt podem executar blocos de shell !`cmd`; cada comando ainda é julgado pelo portão de permissões. Os nomes correspondem à chave que sua configuração de usuário dá ao servidor. Somente nível de usuário; vazio por padrão, então prompts obtidos não executam shell. Optar não é um contorno: no portão apenas uma regra Deny recusa, e uma regra que o portão avalia como Ask executa sem supervisão — a expansão não tem prompt para exibir.',
    'settings.trustedProjectHooks.help' => 'Raízes de projeto cujos .candy-code/hooks.yaml podem ser executados.',
    'settings.trustedProjectMcp.help' => 'Raízes de projeto cujos servidores .mcp.json podem ser iniciados.',
    'settings.trustedProjectSettings.help' => 'Raízes de projeto cujos .candy-code/settings*.json podem definir as chaves do nível de projeto.',
    'settings.turnIdleTimeoutSeconds.help' => 'Segundos que um turno em execução pode ficar sem progresso antes de ser interrompido como travado; tempo ocioso, nunca um total.',
    'settings.ui.imageRenderMode.help' => 'Como imagens geradas são exibidas no terminal; `auto` escolhe o melhor protocolo que o terminal reporta.',
    'settings.ui.mediaDisplayOverrides.help' => 'Ajustes de exibição por modo de renderização (limites de tamanho, alternativas); as chaves são os nomes dos modos de renderização, os valores são os parâmetros de exibição.',
    'settings.vimMode.help' => 'Edição NORMAL/INSERT na caixa de rascunho (i a I A o O Esc, h j k l w b e 0 $ x, dd D cc C yy y p P v V, objetos de texto di" da( ciw, contagens 3dd d2w): movimentos, alteração, exclusão e cópia em NORMAL, digitação literal em INSERT. Um modo, não bindings — nunca aparece em /keys. Aplica-se na próxima tecla após salvar.',
    'settings.voice.apiKey.help' => 'Chave Bearer enviada ao endpoint de transcrição, se ele exigir uma; prefira a forma de placeholder `${VAR}` em vez de um valor literal.',
    'settings.voice.baseUrl.help' => 'URL base HTTP de um endpoint de transcrição compatível com OpenAI (um `/v1` final é mantido); a gravação capturada sai por ali e só por ali. Sem padrão: a entrada de voz permanece OFF até que isso seja definido no nível do usuário.',
    'settings.voice.language.help' => 'Código BCP-47 (`en`, `de`) que força a língua da transcrição; não definido permite que o endpoint detecte.',
    'settings.voice.maxSeconds.help' => 'Limite rígido em segundos de uma gravação (5-600, padrão 120). O limite acompanha o argumento do gravador, então uma gravação órfã se interrompe sozinha.',
    'settings.voice.model.help' => 'ID do modelo enviado com cada solicitação de transcrição; `whisper-1` responde em endpoints compatíveis com OpenAI.',
    'settings.watchFiles.help' => 'Enviar um prompt quando um arquivo salvo contém um comentário terminado em AI! (fazer uma alteração) ou AI? (responder a uma pergunta); comentários AI simples acompanham como contexto. Verificado enquanto o chat está ocioso; apenas comentários salvos após o início disparam, cada um uma vez. Apenas sessões de terminal: o observador roda no processo do terminal, então uma sessão hospedada por `candy-code serve` não observa arquivos.',
    'settings.webFetchMaxBytes.help' => 'Máximo de um corpo obtido mantido em memória; um limite de memória, o limite de saída é o que chega ao modelo.',
    'settings.webFetchTimeoutSeconds.help' => 'Segundos que uma leitura de socket do WebFetch pode travar antes que a obtenção falhe.',
    'settings.webSearchBackend.help' => 'Qual serviço de busca o WebSearch consulta: `searxng` (o padrão) envia cada consulta ao `webSearchEndpoint` configurado; `brave`, `tavily` e `exa` ligam para o host fixo desse serviço e cada um precisa de sua chave de API no ambiente (`BRAVE_SEARCH_API_KEY`, `TAVILY_API_KEY`, `EXA_API_KEY`), sem como apontá-los para outra URL.',
    'settings.webSearchEndpoint.help' => 'URL de busca de uma instância SearXNG confiável (`https://searx.example.org/search`); cada consulta do WebSearch é enviada para lá.',
    'settings.webSearchMaxResults.help' => 'Resultados que um resumo do WebSearch lista, cada um com título, URL e trecho.',
    'settings.webSearchTimeoutSeconds.help' => 'Segundos que uma solicitação de busca pode levar.',
    'settings.webhooks.help' => 'Mapa de nome de hook para {secret, prompt, permissionMode?, rate?}; POST /api/hooks/{name} então injeta o corpo (escapado como não confiável) no prompt e inicia uma sessão em segundo plano. Vazio (padrão) não monta nada. rate é N entregas por minuto por endereço, e por hook no total. bypass-permissions é recusado para hooks no início; um hook sem modo roda no mais restritivo entre o modo do servidor e o padrão. Uma linha também pode nomear signature: {scheme: "github-sha256"|"hmac-sha256", header?, deliveryHeader?}: a rota então verifica um HMAC-SHA256 do corpo bruto (sha256=<hex>) com o secret da linha através do cabeçalho de assinatura, em vez do secret do cabeçalho custom, porque o GitHub não pode enviar cabeçalhos custom; assinaturas com falha alimentam o mesmo lockout por hook, e um id de entrega já visto (X-GitHub-Delivery por padrão para o esquema GitHub; o deliveryHeader configurado para um genérico) responde {"ok": true, "duplicate": true} sem iniciar uma segunda sessão.',
    'settings.webhooksOut.help' => 'Mapa de nome de endpoint para {url, secret, events}; events é uma lista não vazia extraída de turn.completed, session.ended, permission.asked e schedule.fired. Vazio (padrão) não abre nenhuma saída. Lido apenas do nível USER — uma configuração de projeto ou bundle nunca pode adicionar um endpoint de saída. url deve ser https, ou http apenas quando seu host literal é localhost ou um endereço de loopback, e nunca carrega userinfo; secret tem pelo menos 16 caracteres e assina cada entrega com HMAC-SHA256 como X-Candy-Code-Signature (sha256=<hex> sobre o corpo exato) pareado com X-Candy-Code-Timestamp. A entrega é assíncrona no event loop — despachos nunca esperam por uma resposta: um limite de conexão de 2 segundos e um limite de rede de 10 segundos por POST limitam cada entrega (limites de webhook, não um timeout de solicitação LLM), falhas de transporte e respostas 5xx sobem uma escada de retry de 2/8/30 segundos, respostas 4xx e de redirecionamento são definitivas na primeira vez porque redirecionamentos são recusados em vez de seguidos, e uma fila limitada de 128 entregas em andamento descarta novos despachos em caso de overflow em vez de crescer a memória. Lido no início; alterar o mapa tem efeito no reinício.',
    'settings.webhooksOut.refuse' => 'webhooksOut na configuração do usuário é inutilizável: {reason}. Recusando iniciar em vez de entregar a um endpoint meio verificado — corrija o mapa, ou remova a chave para executar sem webhooks de saída.',
    // --- end settings help ---

